quests[76379] = { id = 76379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Murloc und ein Drache kommen in einen Zeitriss...", description = "Grurguglg.\n\nGuuglrllghulgrgl grugll gur. Murgllgllrugl guglrllg murgu gruggullgl. Murglgurrrr gurgll Gurlgul, guruuuurllgr gurgull gurgllglrl.\n\nArgurgulul?\n\n<Ihr seid nicht sicher, was die Worte bedeuten. Die Version von Alexstrasza aus dieser Welt gibt Euch ein Stundenglas und bedeutet Euch, es herumzudrehen. Vermutlich wäre es für Soridormi von Interesse.>", sourceObjective = "Bringt das Azmerlothianische Stundenglas zu Soridormi im Tyrholdreservoir.\n\nBereitgestellter Gegenstand:", completion = "<Soridormi betrachtet das Stundenglas, das Ihr bei Euch tragt.>\n\nDieses Stundenglas wurde von Bronzedrachen hergestellt. Es lässt jemanden zeitweise auf einen anderen Zeitweg springen.\n\nIhr sagtet, die Alexstrasza-Inkarnation dieses Zeitwegs hat es Euch gegeben?\n\n<Soridormi wirft einen Blick auf Alexstrasza.>\n\nDas sollte interessant werden.\n\n<Soridormi dreht das Stundenglas.>", sourceObjectiveStatus = "unverified-source-field" }
quests[76380] = { id = 76380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totenwindtour", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
