quests[76384] = { id = 76384, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Blüte beginnt", description = "Ich spüre eine Veränderung im Wind. Wie in den erwachenden Strahlen der Sonne. Wie Blüten, bevor sie sich entfalten. Eine mächtige, anschwellende Energie, direkt im Herzen des Smaragdgrünen Traums.\n\nDie Blüte. Sie hat begonnen.", sourceObjective = "Erlebt, wie Amirdrassil zu blühen beginnt.", completion = "In diesem Moment ist Amirdrassil am verwundbarsten. Wird seine Blüte als Hoffnungsschimmer in Azeroth erstrahlen... oder wird sie der Herold des Untergangs sein...\n\nEs ist an uns, sein Schicksal zu beschützen. Und wir müssen es beschützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76385] = { id = 76385, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefahrenvoller Gartenbau", description = "Es mag sein, dass wir in der Unterzahl sind, doch dies hier ist mein Herrschaftsgebiet. Und ich kenne einen Weg, um unsere Chancen zu verbessern.\n\nNehmt diesen Beutel mit Samen. Pflanzt sie in der Lauffeuerschlucht und die Feendrachen des Traums werden sie in Treants verwandeln.\n\nMit etwas Glück werden sie die Aufmerksamkeit von unseren vordersten Linien ablenken und unsere Bodentruppen verstärken.", sourceObjective = "Pflanzt 6 Traumsamen in der Lauffeuerschlucht.", completion = "Ich hätte nicht erwartet, dass der Prophet der Flamme sich selbst in die Schlacht stürzt. Uns bleibt vielleicht weniger Zeit, als ich erwartet hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[76386] = { id = 76386, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Aufeinandertreffen von Eis und Feuer", description = "Die Primalisten haben überall in ihrem Lager große Flammenschutze errichtet. Bisher wissen wir nicht, warum. Ich habe unseren Bodentruppen befohlen, das zu untersuchen, aber sie werden dabei auf Schritt und Tritt behindert.\n\nBesonderen Widerstand leisten zwei Feuerelementare, ermächtigt von Fyrakks Schattenflamme.\n\nIhr müsst die Gegend von Gegnern säubern. Ich habe diese Schuppe mit meiner Magie erfüllt. Nutzt sie, um die Elementare und all jene, die Euch im Weg stehen, zu schwächen.", sourceObjective = "Bezwingt Calderamor, Zündrian und 15 feindliche Lauffeuergegner.", completion = "Es freut mich, dass meine Schuppe Euch von Nutzen war. Obwohl ich nicht selber in den Kampf eingreifen kann, so kann ich Euch doch ein bisschen Macht verleihen.\n\nIch werde unseren Bodentruppen befehligen, mit ihren Untersuchungen zu beginnen. Wir müssen herausfinden, warum diese Flammenschutze mit Macht erfüllt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[76387] = { id = 76387, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidigung der Urtume", description = "Fyrakks Truppen in den Himmelssteinfällen drohen bereits damit, uns zu überwältigen. Ich fürchte, nicht einmal die vereinigte Kraft von Schildwachen und Urtumen kann gegen sie bestehen.\n\nDie Urtume tragen die Hauptlast der Offensive. Uns erreichen Berichte, dass die Djaradin versuchen, sie aus einem unbekannten Grund gefangen zu nehmen.\n\nWir können nicht zulassen, dass Igiras schändlicher Plan aufgeht, wie auch immer er aussieht. Ihr müsst die Urtume auf dem Schlachtfeld finden und diejenigen befreien, die gefangen genommen wurden.", sourceObjective = "Befreit die Urtume in den Himmelssteinfällen.", completion = "Eure Hilfe hat die Urtume dabei unterstützt, im Kampf gegen die Djaradin zu bestehen. Aber für wie lange? Wie viele werden wir noch verlieren, bevor dieser Kampf vorüber ist?\n\nSo viele Opfer hat dieser Krieg schon gefordert. So viele sind gefallen. Zu viele.", sourceObjectiveStatus = "unverified-source-field" }
quests[76388] = { id = 76388, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feuer mit Feuer bekämpfen", description = "Die Notizen, die Ihr gefunden habt, haben zusammen mit Merithras Informationen Ashendirs Plan offenbart. Die Flammenschutze, die den Tempel des Quells umgeben, blockieren unserer Verstärkung den Weg.\n\nUnsere Verbündeten werden Fyrakk ablenken, während Ihr und ich uns hinter die gegnerischen Linien begeben, um die Schutze zu zerstören.\n\nDie Himmel sind erfüllt mit Drachen und ich muss sie vertreiben. Sobald Ihr einen Flammenschutz gefunden und seine Verteidigung ausgedünnt habt, gebt mir ein Signal, um es zu zerstören.", sourceObjective = "Zerstört Himmelsfeuergeschütze und markiert die Flammenschutze der Primalisten.", completion = "Fyrakk mag sich zurückgezogen haben, aber er ist noch immer darauf aus, die Barriere zu zerstören, die den Tempel des Quells umgibt. Wir müssen durch die gegnerischen Ränge brechen und ihn aufhalten.\n\nDort werden wir seinen Machenschaften ein Ende setzen, ein für alle Mal.", sourceObjectiveStatus = "unverified-source-field" }
quests[76389] = { id = 76389, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Zeitalter der Sterblichen", description = "Wieder einmal kommen die sterblichen Völker zusammen, um einen Weltenbaum zu verteidigen. Es ist nur passend, dass wir ihre Anstrengungen mit einem Relikt aus dem letzten Kampf unterstützen. Das Horn des Cenarius.\n\nIch vertraue Euch das Horn an, {name}. Nutzt es, um unseren Verbündeten den Segen von Cenarius zu verleihen. Mit etwas Glück können wir uns dann einen Weg durch Fyrakks Truppen bahnen und einen Weg zum Tempel öffnen.\n\nUnd vergesst nicht, Eure Stärke einzusetzen. Jeder gefallene Gegner ist einer weniger, der zwischen uns und Fyrakk steht.", sourceObjective = "Lasst das Horn von Cenarius erklingen, während Ihr Euch in der Nähe der Helden von Azeroth befindet, und bahnt Euch einen Weg durch Fyrakks Truppen.", completion = "Unsere Verbündeten kämpfen mit dem Segen des Cenarius! Es ist nur eine Frage der Zeit, bis in den Reihen von Fyrakks Truppen Löcher entstehen und sie vor uns fliehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76390] = { id = 76390, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unbequemlichkeitsgebühren", description = "Ich habe keine Ahnung, wie Ihr mich gefunden habt oder was Euch dazu bewogen hat, einen Toten mit Weihwasser zu bespritzen, aber wir sind uns doch beide einig, dass Ihr mir etwas schuldet. Das Zeug tut weh!\n\nZu Eurem Glück mag ich Bestechung mehr als Nickerchen. Ich werde Euren schlechten Einstand mit Freuden vergessen, damit wir beide beste Kumpel sein können. Eine Hand wäscht die andere.\n\nWas meint Ihr?", sourceObjective = "Zackett Schädelschmetter in den Sparren von Naxxramas hat angeboten, Eure Fehltritte zu vergessen, wenn Ihr ihm einige Gegenstände bringt.", progress = "He, das ging schnell! Was habt Ihr vergessen?", completion = "Sieh sich einer diese Ausbeute an! Ihr habt sogar an meinen Kaffee gedacht. Niemand denkt an den Kaffee...\n\nIch mag Euch. Wir werden gemeinsam große Dinge vollbringen. Damit meine ich, dass Ihr mir Geißelsteine bringen werdet, und ich tausche sie gegen all die Beute ein, die Abenteurer alter Zeiten zurückließen, als sie ins Gras bissen. Hätten wieder aufstehen sollen, als sie die Chance hatten, wie ich!\n\nIch packe mein Zeug zusammen und treffe Euch im inneren Ring.", sourceObjectiveStatus = "unverified-source-field" }
quests[76394] = { id = 76394, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatten mit Aroma", description = "Ich will eine Mahlzeit kreieren, die über das Gewöhnliche hinausgeht und die selbst der Kaiser nicht ablehnen würde.\n\nIch benötige Zutaten aus den dunkelsten Schatten, um diese außergewöhnliche Mahlzeit zuzubereiten. Viele halten diese Zutaten für verboten, aber in meinen Händen werden sie zu einer Harmonie aus Licht und Schatten.\n\nBitte helft mir und sammelt folgende Zutaten: schattenblinder Barsch, dunkelheitsgenährte Frühlingszwiebeln und ein Fläschchen mit Zwielichtgewürz.", sourceObjective = "Beschafft 10 schattenblinde Barsche, 5 dunkelheitsgenährte Frühlingszwiebeln und eine Phiole mit Zwielichtgewürz.", progress = "Habt Ihr alle Zutaten gefunden?", completion = "Nun wird Magie geschehen. Bitte kostet diese Kreation selbst.", sourceObjectiveStatus = "unverified-source-field" }
quests[76395] = { id = 76395, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Verderbers", progress = "Ich muss Euch wohl kaum die ganze Tirade über Geißelsteine runterbeten, {name}, also komme ich gleich zur Sache. Ich bin SEHR interessiert daran, meine Sammlung zu erweitern, und Ihr seid SEHR an dem Zeug interessiert, das ich anzubieten habe.\n\nGeißelsteine des Verderbers sind bei Weitem am mächtigsten, also kommen wir ins Geschäft, wenn Ihr auch nur ein paar habt.\n\nUnd sagt der Argentumdämmerung nichts davon! Das ist unser kleines Geheimnis, alles klar?", completion = "Und noch eine Ladung Geißelsteine von meinem besten Kumpel, {name}! Ich danke Euch erneut. Die passen perfekt zu meinem restlichen Lager. Macht weiter so, dann muss ich mir ein neues Lager suchen!\n\nHier, das ist für Eure Mühen. Ich mag dieses kleine Tauschgeschäft, dass wir hier spielen. Machen wir weiter so.\n\nAber nein, ich werde Euch immer noch nicht sagen, was ich damit mache." }
quests[76396] = { id = 76396, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geißelsteine des Eindringlings", progress = "Ich muss Euch wohl kaum die ganze Tirade über Geißelsteine runterbeten, {name}, also komme ich gleich zur Sache. Ich bin SEHR interessiert daran, meine Sammlung zu erweitern, und Ihr seid SEHR an dem Zeug interessiert, das ich anzubieten habe.\n\nGeißelsteine des Eindringlings sind ziemlich leicht zu finden, also müsst Ihr mir eine ganze Menge bringen.\n\nUnd sagt der Argentumdämmerung nichts davon! Das ist unser kleines Geheimnis, alles klar?", completion = "Und noch eine Ladung Geißelsteine von meinem besten Kumpel, {name}! Ich danke Euch erneut. Die passen perfekt zu meinem restlichen Lager. Macht weiter so, dann muss ich mir ein neues Lager suchen!\n\nHier, das ist für Eure Mühen. Ich mag dieses kleine Tauschgeschäft, dass wir hier spielen. Machen wir weiter so.\n\nAber nein, ich werde Euch immer noch nicht sagen, was ich damit mache." }
quests[76397] = { id = 76397, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynnetappe", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76398] = { id = 76398, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftüberlegenheit", description = "Die Drachenschwärme sind da. Wir werden die Himmel zurückfordern! Und Ihr könnt uns dabei helfen, das Blatt zu unseren Gunsten zu wenden.\n\nSteigt auf Euren Drachen und nehmt die Gegner über uns ins Visier. Ihr müsst Euch nur auf sie stürzen und ihre Truppen überraschen. Euer Drache wird sich um den Rest kümmern.", sourceObjective = "Bezwingt 15 gegnerische Protodrachen, die über dem Feld der Flammen fliegen, indem Ihr sie mit Eurem Drachenreittier angreift.", progress = "Je schneller wir Fyrakks Truppen ausschalten können, umso schneller können wir zum Tempel vordringen und diesem Wahnsinn ein Ende setzen.", completion = "Exzellent. Fyrakks Truppen wanken unter Eurem Angriff.\n\nWir Drachen übernehmen von hier an, {name}. Dies ist unser Traum und ich werde diese Eindringlinge nicht länger ertragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76399] = { id = 76399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynnetappe - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76400] = { id = 76400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynnetappe - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76401] = { id = 76401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo der Feuerlande", description = "Wir haben endlich die feindliche Front durchbrochen, aber der Prophet der Flamme versperrt uns den Weg. Und er hat seine ganze Macht entfesselt.\n\nDer Prophet muss besiegt werden, wenn wir Hoffnung haben wollen, den Tempel zu erreichen. Ich bitte Euch, ihn zu stellen, Champion. Wir werden so lange seine Truppen zurückhalten.\n\nDas Ende ist in Sicht. Lasst uns diesen Krieg endlich beenden.", sourceObjective = "Bezwingt den Propheten der Flamme.", completion = "Fyrakk hat die Barriere durchbrochen! Er muss von Verzweiflung gepackt worden sein, als er unsere Truppen näherkommen sah. Wenn man so viel Schattenflamme auf einmal einsetzt...", sourceObjectiveStatus = "unverified-source-field" }
quests[76402] = { id = 76402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Amirdrassil, Hoffnung des Traums: Fyrakk", description = "Fyrakk mag den Tempel betreten haben, aber unser Kampf ist nicht vorbei. Dank Eurer Anstrengungen konnten wir durch seine Truppen stoßen. Es ist immer noch Zeit, ihn aufzuhalten.\n\nIhr müsst Eure Verbündeten versammeln und Fyrakk in den Tempel des Quells folgen. Wir decken Eure Flanke.\n\nSeid versichert, dass Ihr heute nicht nur Amirdrassil beschützt, {name}. Ganz Azeroth wird brennen, wenn Fyrakk den Weltenbaum für sich beansprucht. Er muss aufgehalten werden, hier und jetzt. Dies ist das letzte Gefecht.", sourceObjective = "Betretet Amirdrassil, Hoffnung des Traums, und besiegt Fyrakk.", completion = "Amirdrassil ist gerettet und damit ganz Azeroth. Fyrakks Niederlage hat dies sichergestellt.\n\nVom Champion der Dracheninseln zum Retter des Smaragdgrünen Traums. Alle Drachenschwärme stehen tief in Eurer Schuld, {name}. Und wir werden dies so schnell nicht vergessen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76403] = { id = 76403, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inkarnationenchaos", description = "Wir müssen herausfinden, was genau Fyrakk vorhat. Er hält seine Truppen vom Baum fern, doch wir wissen nicht, warum.\n\nIch kann Erkundigungen einziehen, aber ein direkter Konflikt mit Fyrakk würde unserer Sache im Moment nicht nützen.\n\nFolgt mir tiefer in den Traum. Es gibt im Norden ein Lager der Primalisten. Lasst uns dort anfangen, damit wir diesem Wahnsinn ein Ende machen können.", sourceObjective = "Sprecht mit Vyranoth nahe des Lagers der Primalisten.", completion = "Meine Klauen sind hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[76404] = { id = 76404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rädchen im Getriebe", description = "<Dieses Zahnrad flog aus einer mechanisierten Kreatur heraus, als Ihr sie zurück auf ihren Zeitweg schicktet.\n\nVom Aussehen her ähnelt es der Mechagnomtechnologie, wobei es etwas schlanker und raffinierter ist.\n\nEs zeigt eine kleine Inschrift.\n\nSoridormi ist sicher sehr daran interessiert.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück, nachdem Ihr den Zeitriss abgeschlossen habt.", completion = "<Soridormi entziffert die Inschrift auf dem Zahnrad.>\n\n\"Mechanisierung ist der einzige Weg zu wahrem Frieden.\"\n\nEin interessanter Gedanke, aber auch eine Lüge. Dieser Zeitweg entwickelte offensichtlich weiter Waffen für den Krieg.\n\nDa frage ich mich: Wenn sie nicht gegeneinander kämpften, wogegen kämpften sie dann?\n\nIch lege dies auf die Tische, falls Ihr es Euch später ansehen möchtet.", sourceObjectiveStatus = "unverified-source-field" }
quests[76406] = { id = 76406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Sünden des Aschenbringers", description = "<Als Ihr Euch der Klinge nähert, spürt Ihr, wie sie nekromantische Macht aussondert.\n\nVielleicht solltet Ihr das Schwert mit Stoff umwickeln und lieber nicht direkt berühren.\n\nSoridormi ist sicher sehr daran interessiert.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück, nachdem Ihr den Zeitriss abgeschlossen habt.", completion = "<Als Ihr Soridormi den Gegenstand überreichen wollt, weicht sie instinktiv zurück.>\n\nEinen näheren Blick darauf erspare ich mir lieber, danke.\n\nWir werden es zu den übrigen Gegenständen legen. Die schwarze Klinge kann nekromantische Energie aufsaugen. Das sollte den Umgang damit erleichtern.", sourceObjectiveStatus = "unverified-source-field" }
quests[76407] = { id = 76407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heute nicht, Schicksal", description = "Eternus will uns zeigen, was geschehen ist. Ich glaube, sie will außerdem die Vergangenheit verändern.\n\nNormalerweise würde ich diese Idee nicht einmal erwägen, aber wir müssen die Ewigen verstehen, wenn wir weiterkommen wollen.", sourceObjective = "Betretet den Zeitriss, um die Vergangenheit zu sehen.", progress = "Eternus will uns etwas zeigen... Ich gehe davon aus, viel über sie zu erfahren.", completion = "Ist es möglich, Moraidormi zu helfen? Auf den ersten Blick scheint es so, als ob wir das können.\n\nAber ich spüre, dass hier irgendetwas... nicht in Ordnung ist. Warum war Vexemia hinter ihr her? Was wird passieren, wenn Vexemia nicht weitermacht?\n\nMir scheint, wir übersehen da etwas.", sourceObjectiveStatus = "unverified-source-field" }
quests[76410] = { id = 76410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dunkler Ruf", description = "Bewohner Azeroths,\n\ndürstet es Euch nach Macht? Nach einem besseren Leben, nach... mehr?\n\nMehr Freiheit.\n\nMehr Respekt.\n\nMehr Furcht.\n\nWollt Ihr Hexenmeister werden?\n\nWenn Ihr eine dieser Fragen mit \"Ja\" beantwortet habt, dann sucht meinen bescheidenen Diener Phineas auf.\n\nIn Versuchung,\n\nMadame Schatten", sourceObjective = "Redet mit Assistent Phineas im Magierviertel in Sturmwind.", completion = "Noch ein Interessent, doch halt! {name}? Sieh an...\n\nIhr seid genau der {class}, nach der wir gesucht haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[76416] = { id = 76416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dem Feuer entgegen", description = "Amirdrassil schöpft Energie aus dem Tempel des Quells, um sich auf seine Blüte vorzubereiten. Die Barriere, die den Tempel schützt, wird Fyrakks Angriff nicht mehr lange standhalten.\n\nIch habe Boten durch ganz Azeroth geschickt, um Verstärkung zu erbitten, aber sie haben ihr Ziel noch nicht erreicht. Etwas versperrt ihnen den Weg in den Traum. Im Moment müssen wir uns auf die vorhandenen Kräfte verlassen.\n\nIch bitte Euch, zum Tiefgrünen Pass zu reisen. Wenn es jemanden gibt, den ich an meiner Seite haben möchte, dann seid Ihr es.", sourceObjective = "Trefft Alexstrasza am Tiefgrünen Pass.", completion = "Wir sind dankbar über Eure Ankunft, {name}.\n\nUnsere Truppen sind versammelt, aber die Chancen stehen gegen uns. Ohne Verstärkung werden wir hier nicht mehr lange durchhalten. Hoffen wir, dass wir Fyrakks Aufmerksamkeit ablenken können, bis die Blüte vollendet ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[76419] = { id = 76419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gewalt wird das schon lösen", description = "Seid Ihr etwa nicht der Meinung, dass Moraidormi gerettet werden kann? Wir Ewigen retten oft diejenigen, von denen wir denken, dass sie unnötig gelitten haben. Ob sie es wert sind oder nicht.\n\nAngenommen, Mori ist zu nahe an den Höhlen der Zeit östlich von uns gestorben. Wenn man hier zu viel Zeitmagie einsetzt, könnte das... schwerwiegende Folgen haben.\n\nAber es muss schnell gehen. Chronolord Deios besaß Artefakte, mit denen man die Zeit wirkungsvoll zurückspulen konnte. Nun besitzt sie der bronzene Drachenschwarm.\n\nWir werden die Zeit zurückdrehen und dann Vexemia vernichten.\n\nGanz einfach.", sourceObjective = "Dreht die Zeit zurück und verteidigt Moraidormi gegen Vexemias Angriff.", progress = "Das wird leicht. Da stellt sich die Frage, warum der bronzene Drachenschwarm das nicht schon früher getan hat!", completion = "Das... lief nicht so wie geplant.\n\nAber ich werde nicht aufgeben! Wir können die Zeit einfach erneut zurückspulen, bis wir es schaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76420] = { id = 76420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmetterlingseffekte", description = "Wir wurden von ihren Gefährten überwältigt. Moraidormi wurde dennoch getötet.\n\nIch brauche eine neue Strategie, die sie wirklich beschützt. Nur sie ist wichtig. Spult die Zeit erneut zurück, einschließlich Eurer Taten.\n\nNachdem das getan ist, werde ich die Zeit anhalten. Dann können wir für sie Verteidigungsmaßnahmen errichten.", sourceObjective = "Dreht die Zeit zurück, errichtet Verteidigungsmaßnahmen für Moraidormi und testet sie.", progress = "Was können wir noch tun?", completion = "Das war kein bisschen besser.\n\nEs... Es war sogar eindeutig schlimmer.\n\nIch versuche, nicht die Konzentration zu verlieren. Was, wenn wir erneut angreifen würden oder...", sourceObjectiveStatus = "unverified-source-field" }
quests[76421] = { id = 76421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir schmieden unser Schicksal", description = "Wir müssen nur stärker und schneller sein!\n\nWir können es nicht so lassen, nicht nachdem auch die Eier zerstört wurden.\n\nIch werde mir etwas anderes einfallen lassen. Die Zeit neu starten und...\n\n<Eternus seufzt.>\n\nVielleicht sollte ich auf Nozdormu hören. Er sagt mir ständig, dass ich etwas \"übersehen\" habe...", sourceObjective = "Spult die Geschichte erneut zurück und hört, was Nozdormu zu sagen hat.", progress = "Es erscheint mir sinnlos, nichts zu tun, aber ich werde Geduld wahren. Vorerst.", completion = "Moraidormi. Der Welpe. Ich verstehe jetzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76422] = { id = 76422, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unendlichkeit und noch viel weiter", description = "Wenn wir weiterhin in die Vergangenheit blicken, verpassen wir die Gegenwart... oder sogar die Zukunft.\n\nKehren wir nach Thaldraszus zurück.\n\nMacht Euch keine Sorgen um diese Zeitbruchelementare. Auch sie werden mit der Zeit heilen.\n\nSo, wie wir alle.", sourceObjective = "Kehrt in die Gegenwart zurück und schaut bei Chromie vorbei.", progress = "Ich hoffe, dass uns diese Erfahrung zusammenbringen kann.", completion = "Wir alle haben heute etwas Neues gelernt.\n\nIch ebenfalls.\n\nDie Zeit lehrt uns täglich etwas Neues. Es ist liegt in unserer Verantwortung, immer weiter zuzuhören und zu lernen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76423] = { id = 76423, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Grenzen", description = "Nachdem wir uns den Ewigen und, nun ja, mir selbst gestellt haben... haben wir eine Menge, worüber wir nachdenken müssen.\n\nEternus, eine der Ewigen, hat anscheinend auch viel nachgedacht.\n\nDie Ewigen wollen Nozdormu seine ewige Form annehmen lassen, Murozond. Das wollen wir nicht. Und nachdem sie von Nozdormu erfahren hat, könnte Eternus vielleicht davon überzeugt werden, das ebenfalls nicht zu wollen.\n\nIch habe ein Treffen zwischen Nozdormu und Eternus organisiert, damit sie reden können. Aber ich will, dass dort noch jemand dabei ist... falls es schiefläuft.", sourceObjective = "Schaut bei Eternus und Nozdormu vorbei.", completion = "Das wird ein... heikles Treffen. Lasst am besten mich reden.", sourceObjectiveStatus = "unverified-source-field" }
quests[76425] = { id = 76425, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angesehen bei den Traumwächtern", description = "Champion! Bitte schenkt mir einen Moment Eurer Zeit.\n\nWir möchten all Euren Bemühungen Anerkennung zollen. Sucht mich im Zentrallager auf. Wir wollen Euch ein Zeichen unserer Wertschätzung überreichen.", sourceObjective = "Sprecht mit Hüter Amrymn im Zentrallager.", completion = "Vielen Dank für alles, was Ihr für uns getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76426] = { id = 76426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Strecken des Kalimdorpokals", description = "Die Reiter von Azeroth haben viel von uns gelernt. Nun wird es Zeit, ihren Kampfgeist auf die Probe zu stellen, und Euren gleich dazu, <Himmelsreiter/Himmelsreiterin>.\n\nMeine bronzenen Kameraden sind nach Kalimdor gereist, um neue Herausforderungen zu entwickeln. Sie erwarten Euch mit zahlreichen Rennen auf dem ganzen Kontinent.\n\nSeid Ihr der Aufgabe gewachsen?", sourceObjective = "Fliegt durch die Strecken des Kalimdorpokals.", completion = "Ihr gebt den anderen Drachenreitern den Weg vor! Wenn der Kalimdorpokal weitergeht, könnt ihr dort weitere Rennen finden und Euren Schneid unter Beweis stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76427] = { id = 76427, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein dunkler Ruf", description = "Bewohner Azeroths,\n\ndürstet es Euch nach Macht? Nach einem besseren Leben, nach... mehr?\n\nMehr Freiheit.\n\nMehr Respekt.\n\nMehr Furcht.\n\nWollt Ihr Hexenmeister werden?\n\nWenn Ihr eine dieser Fragen mit \"Ja\" beantwortet habt, dann sucht meinen bescheidenen Diener Phineas auf.\n\nIn Versuchung,\n\nMadame Schatten", sourceObjective = "Redet mit Assistent Phineas in der Kluft der Schatten in Orgrimmar.", completion = "Noch ein Interessent, doch halt! {name}? Sieh an...\n\nIhr seid genau der {class}, nach der wir gesucht haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[76429] = { id = 76429, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kalimdorpokal beginnt", description = "<Himmelsreiter/Himmelsreiterin>! Ihr habt Lord Andestrasz gerade verpasst. Er ist auf der Suche nach fähigen Himmelsreitern wie Euch, die sich in den neuen Rennen messen!", sourceObjective = "Sucht Lord Andestrasz in Valdrakken auf.", completion = "Danke für Euren Besuch, Drachenreiter!", sourceObjectiveStatus = "unverified-source-field" }
quests[76430] = { id = 76430, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Start der Wichteleien", description = "Finsterste Grüße, {race}. Ähem, ja. Ja! Finsterste Grüße, so ist es.\n\n<Der schlaksige Mann scheint sich plötzlich daran zu erinnern, wo er ist.>\n\nIm Namen meines Schutzpatrons lade ich Euch ein, zum Dunkelmond-Jahrmarkt zu reisen. Der Jahrmarkt! Wer liebt ihn nicht? Ja. Ja!\n\nÄhem.\n\nSie verlangt nach Eurer Anwesenheit, das tut sie! Unsere Dame des Mitternachtsmonds. Die Dame der Dunkelheit! Die Mutter der Krähen...\n\n...Madame Schatten.", sourceObjective = "Reist zum Dunkelmond-Jahrmarkt.", completion = "Ihr seid... kleiner, als ich in Erinnerung hatte.", sourceObjectiveStatus = "unverified-source-field" }
quests[76433] = { id = 76433, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Äscherne Erde", description = "Es scheint, als hätten die Druiden der Flamme keine Zeit verschwendet, um ihren Einfluss auszuweiten.\n\nTief in diesen Grabhügeln hat eine Art der Verderbnis Wurzeln geschlagen. Sie wird sich unkontrolliert ausbreiten und die gesamte Höhle verzehren, bevor sie sich nach außen ausbreitet und den Rest des Traums bedroht.\n\nDie Zeit ist knapp, {name}. Dringt in den Grabhügel ein, sucht die Quelle der sich ausbreitenden Flamme und löscht sie, bevor die schwelende Glut wachsen und sich ausbreiten kann.", sourceObjective = "Findet die Quelle der Flammenverderbnis des Grabhügel und löscht sie aus.", completion = "<Tyrandes Gesichtsausdruck schwankt zwischen Traurigkeit und Überzeugung.>\n\nDies sind nicht Fandral Hirschhaupts Druiden der Flamme. Zu denken, dass jemand, der so gütig und mitfühlend ist wie Norana, sich selbst zu ihnen zählen würde...\n\nWir werden vielleicht nie wirklich die Tiefe der Narben verstehen, die die gefallenen Äste von Teldrassil hinterlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[76434] = { id = 76434, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch nicht verloren", description = "Die Flamme hat hier nicht aus einer Laune heraus Wurzeln geschlagen.\n\nZweifelsohne gibt es Diener der Feuerlande, die sich hier versteckt halten und versuchen, ihre Flamme auf die Kreaturen zu übertragen, die in diesen Grabhügeln leben. Wir müssen alles in unserer Macht Stehende tun, um diejenigen zu retten, die noch gerettet werden können, und den Ketzern, die hier lauern, schnelle Gerechtigkeit widerfahren lassen.", sourceObjective = "Rettet die Bewohner des Grabhügels von Sor'theril.", progress = "Wenn auch nur eine leidende Seele in diesen Hügeln verbleibt, müssen wir alles tun, um sie zu retten.", completion = "Es vergeht kein Tag, an dem ich nicht derer gedenke, die in Teldrassil gefallen sind, verzehrt von einem Feuer, das ich nicht löschen konnte. \n\nOb Kaldorei oder Dryade, ich werde nie wieder zulassen, dass die Schreie der Gequälten ungehört verhallen. Nicht, solange ich noch atme.", sourceObjectiveStatus = "unverified-source-field" }
quests[76435] = { id = 76435, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Qualmende Gehölz", description = "Andi'thur berichtet mir von Rauch, der aus einem Hain im Westen aufsteigt. Noranas neue Verbündete sind nicht gerade von der feinfühligen Sorte.\n\nEs ist mir egal, was ihre Beweggründe sind. Ich werde ihr nicht erlauben, einen weiteren Zentimeter dieses Landes in Brand zu setzen. Reitet zu den westlichen Hainen. Wie auch immer die Druiden der Flamme ihre sogenannte Wiedergeburt anstreben, wir werden alles tun, um sie aufzuhalten.", sourceObjective = "Untersucht das Qualmende Gehölz.", completion = "Norana... Ihr wart immer eine so freundliche und ruhige Seele. Die Vorstellung, dass Ihr dabei helft, so etwas Schlimmes in Gang zu setzen.\n\n<Tyrande seufzt.>\n\nEs gibt viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[76436] = { id = 76436, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Rest Hoffnung", description = "Es ist nur eine Frage der Zeit, bis Fyrakks Streitkräfte unsere eigenen dezimieren. Und dann wird ihn nichts mehr davon abhalten, in den Tempel des Quells einzudringen.\n\nWenn der Prophet der Flamme dafür verantwortlich ist, dass unsere Verstärkung nicht in den Traum eindringen kann, muss es irgendeine Aufzeichnung oder Mitteilung über seinen Plan geben. Wir müssen sie nur finden.\n\nSucht nach Mitteilungen unter Fyrakks Streitkräften in den Himmelssteinfällen. Wenn wir ihre Bemühungen auf irgendeine Weise stören können, haben wir vielleicht eine Chance, das Blatt zu wenden.", sourceObjective = "Sammelt 8 Pergamentreste von Fyrakks Truppen in den Himmelssteinfällen.", progress = "Wenn Fyrakk den Tempel des Quells betritt, wird nicht nur Amirdrassil brennen. Ganz Azeroth wird mit ihm brennen.", completion = "Hoffen wir, dass wir aus den von Euch gesammelten Mitteilungen etwas lernen können.\n\n<Alexstrasza studiert die Notizen, die Ihr ihr übergeben habt. Ihr Gesichtsausdruck ändert sich langsam von bedrückt zu hoffnungsvoll.>\n\nIhr habt uns vielleicht alle gerettet, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76437] = { id = 76437, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brennender Boden", description = "Wir erlaubten uns, abgelenkt zu werden. Wir dachten, die Druiden der Flamme wären uns in den Traum gefolgt, dabei waren sie eindeutig vor uns da.\n\nDa Amirdrassil so nah ist, können wir nicht zulassen, dass sie hier ihre äschernen Wurzeln ausbreiten. Lasst ihre Gefangenen frei. Plündert ihre Vorräte. Tut, was immer ihr könnt, um sicherzustellen, dass sich diese brennende Verderbnis nicht weiter ausbreitet.", sourceObjective = "Greift im Qualmenden Gehölz ein.", completion = "Auch wenn sie von der Flamme verderbt sind, haben diese Druiden den Weg zum Traum nicht vergessen. Es wird schwierig sein, sie gänzlich draußen zu halten.\n\nDoch ohne eine geeignete Operationsbasis werden sie es schwer haben, ihren Einfluss auszuweiten. Eure Taten heute werden dazu beitragen, Amirdrassils Sicherheit vor dem sich ausbreitenden Feuer zu gewährleisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[76438] = { id = 76438, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashigala", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76439] = { id = 76439, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashigala - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76440] = { id = 76440, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurubashigala - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76441] = { id = 76441, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unerbittliche Vergeltung", description = "Die Druiden der Flamme werden nicht zulassen, dass Ihr ungehindert weitergeht, sobald Eure Absichten hier deutlich werden.\n\nSie sind meine Angehörigen, meine Brüder und Schwestern unter Elune... Aber sie versuchen, alles zunichte zu machen, wofür wir uns eingesetzt haben. Ihre Machenschaften würden unzählige Leben zu einem alles verzehrenden Inferno verdammen.\n\nDas werde ich nicht zulassen. Wir können es nicht zulassen.\n\nUnterbrecht ihre Rituale. Zerstört ihre Vorräte. Wenn sie ihre Klingen gegen Euch erheben, schlagt sie nieder.", sourceObjective = "Greift im Qualmenden Gehölz ein.", completion = "Der Gedanke, dass nach allem, was wir durchgemacht haben, ein Druide es wagen könnte, den Traum auf diese Weise zu entstellen.\n\n<Tyrande runzelt die Stirn.>\n\nDiese \"Druiden\" sind eine Beleidigung für das Leid, das die Kaldorei ertragen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[76442] = { id = 76442, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trostlose Hoffnung", description = "Ihr kommt gerade rechtzeitig. Norana lauert gleich hinter dem Bergkamm. Sie scheint an einer Art Ritual teilzunehmen - zusammen mit einem Mann, der ihr Anführer zu sein scheint.\n\nDies sind machtvolle Druiden, und ihre Stärke wird durch ihre Verbindung zu den Feuerlanden noch verstärkt. Es wäre töricht, sie alle auf einmal zu bekämpfen.\n\nDoch das Mindeste, was wir tun können, ist, ihr Ritual zu stören. Wenn wir sie in die Flucht schlagen, verschaffen wir uns Zeit - und die Möglichkeit, den Vormarsch an anderer Stelle fortzusetzen.", sourceObjective = "Unterbrecht das Ritual der Druiden der Flamme.", completion = "Dieser sogenannte Prophet gibt vor, die Interessen der Kaldorei zu vertreten, aber ich erkenne seine Absichten. Er giert nach Macht und nutzt die Angst und das Leid der Kaldorei aus, um sie zu erlangen.\n\nSein Werk darf nicht fortgesetzt werden. Nicht, solange ich noch atme.\n\nHier haben wir vorerst alles getan, was wir können. Wir müssen nach Amirdrassil zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[76443] = { id = 76443, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die drohende Glut", description = "Die Druiden der Flamme sind nichts weiter als Handlanger von Fyrakk und seinesgleichen. Dennoch stellen sie eine ernste Bedrohung für das Wohlergehen von Amirdrassil dar, ganz zu schweigen vom übrigen Traum.\n\nDer Sieg, den wir hier heute errungen haben, war hart erkämpft, aber er hat nur dazu gereicht, die Flut einzudämmen. Zweifellos haben sich der Prophet und die Priesterin bereits mit ihren früheren Verbündeten wiedervereint.\n\nWir sollten zu Merithra zurückkehren. Sie muss davon erfahren.", sourceObjective = "Kehrt zu Merithra bei Amirdrassil zurück.", completion = "Ich bin froh, dass Ihr zurückgekehrt seid, {class}. Ich wünschte, ich könnte Euch einen Moment Ruhe gönnen für all die harte Arbeit, die Ihr geleistet haben.\n\nLeider können wir uns diesen Luxus nicht leisten. Wo eine Flamme erlischt, lodert eine andere auf. Amirdrassil bleibt in Gefahr.", sourceObjectiveStatus = "unverified-source-field" }
quests[76445] = { id = 76445, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenschmiedeerkundung", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76446] = { id = 76446, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenschmiedeerkundung - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76447] = { id = 76447, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eisenschmiedeerkundung - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76448] = { id = 76448, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal von Schuppenkommandant Abereth", description = "Unseren Kollegen zufolge wurden in dieser Höhle angehende Schuppenkommandanten geprüft.\n\nEntschuldigt. Entweder wurden sie hier geprüft oder beigesetzt. Die Prüfungen waren so schwer, dass es meistens aufs Gleiche hinauslief.\n\nWir suchen nach einem uralten Schuppenkommandanten, der in unseren Aufzeichnungen als \"Die spaltende Klinge\" bezeichnet wird: Ein vielversprechender junger Dracthyr, dessen Zukunft irgendwo in der Nähe dieser Höhle abrupt ein Ende fand. Vielleicht finden wir heraus, wie seine Geschichte endet.", sourceObjective = "Findet die drei Abstimmungsrelikte.", progress = "Ohne diese Abstimmungsrelikte werden wir das Geheimnis nicht lösen können, {name}.", completion = "Aha! Gebt sie her, dann kalibriere ich Eure Brille.", sourceObjectiveStatus = "unverified-source-field" }
quests[76449] = { id = 76449, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der endlose Konflikt", description = "<Neben der Leiche eines Soldaten der großen glorreichen Allianz bemerkt Ihr ein Buch.\n\nIhr blättert es durch und stellt fest, dass es sich um eine Art Tagebuch handelt.\n\nTeile davon sind durch eine Ölpfütze unleserlich geworden.\n\nSoridormi ist sicher sehr daran interessiert.>", sourceObjective = "Bringt das ölgetränkte Logbuch zu Soridormi im Tyrholdreservoir.\n\nBereitgestellter Gegenstand:", completion = "<Ihr haltet Soridormi das noch immer vor Öl triefende Buch hin und sie nimmt es mit spitzen Fingern entgegen.>\n\nIch weiß nicht, ob ich unbedingt einen Blick hinein werfen will. Ihr sagt, Teile davon sind noch entzifferbar?\n\nNun gut... Ich schätze, wir können es zu den anderen Sachen legen.\n\nNachdem wir es richtig gesäubert haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[76453] = { id = 76453, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprung in der Tafel", description = "<Die gesprungene Steintafel fällt Euch sofort ins Auge.\n\nAls Ihr sie aufhebt, bemerkt Ihr, dass sie deutlich schwerer ist, als sie aussieht.\n\nSoridormi ist sicher sehr daran interessiert.>", sourceObjective = "Bringt die gesprungene Steintafel zu Soridormi im Tyrholdreservoir.\n\nBereitgestellter Gegenstand:", completion = "<Als Soridormi die Tafel entgegennimmt, lässt sie sie beinahe fallen, weil sie überraschend schwer ist.>\n\nStammt die aus dem Schwarzen Imperium?\n\nSie... sieht nicht verderbt aus. Aber vielleicht sollten wir trotzdem vorsichtig sein.\n\nIch werde jemanden bitten, herzukommen und sie zu läutern, um auf Nummer sicher zu gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76456] = { id = 76456, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Götzen einsetzen", description = "Ah, der Götze von Ohn'ahra! Lasst ihn uns nutzen, um Juwelen zu finden. Ich habe in Valdrakken drei Juwelen versteckt, gleich hier in der Nähe und alle im Freien.\n\nDer Götze zeigt die Juwelen an, wenn Ihr in der Nähe seid.\n\nKommt zurück, wenn Ihr sie aufgespürt habt.", sourceObjective = "Setzt den Götzen von Ohn'ahra ein, um drei versteckte Juwelen zu finden, und sprecht dann mit Bewahrerin Kathos.", progress = "Habt Ihr die Juwelen gefunden?", completion = "Ihr habt ein Auge dafür, verlorene Gegenstände zu finden, {name}. Das Talent wird Euch gute Dienste leisten.\n\nOder besser gesagt... UNS gute Dienste leisten.", sourceObjectiveStatus = "unverified-source-field" }
quests[76459] = { id = 76459, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Widerstand", description = "<Vor Euch seht Ihr zweifelsohne eine Nachtelfe, die nicht der Verderbnis anheimgefallen ist, wenn auch deutlich verwilderter und unterernährter, als Ihr es gewohnt seid.>\n\nSchöne Welt. Keine Legion. Kein Übel.\n\nWenn Ihr könnt, schickt Hilfe. Suramar, fragt nach Tyrande.\n\n<Soridormi dürfte das sehen wollen.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück, nachdem Ihr den Zeitriss abgeschlossen habt.", completion = "<Soridormi sieht Euch fassungslos an, als Ihr ihr eine Karte für Suramar überreicht. Erst als Ihr ihr die Umstände erklärt, ändert sich ihr Gesichtsausdruck.>\n\nUnglaublich. Diese Welt wird seit Zehntausend Jahren von der Legion unterjocht und doch gibt es noch immer einen Widerstand.\n\nIch wünschte, wir könnten die tapferen Kämpfer unterstützen, aber leider dürfen wir nicht in einem anderen Zeitweg intervenieren.\n\nEine unbefriedigende Antwort, das ist mir bewusst.", sourceObjectiveStatus = "unverified-source-field" }
quests[76460] = { id = 76460, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieber einen Drachen in der Hand als zwei im Horst", description = "Ah, {name}, schön, Euch zu sehen!\n\nIhr kommt genau zur rechten Zeit. Mir wurde aufgetragen, mögliche Verbündete zum Schutz des Weltenbaums zu finden.\n\nEure Erfolge sprechen für sich: Ich wäre für Eure Hilfe in dieser Angelegenheit sehr dankbar.\n\nHabt Ihr Interesse, Euch diplomatisch zu betätigen?", sourceObjective = "Sprecht mit Furorion über seine möglichen Verbündeten.", progress = "Ich bin doch recht aufgeregt, diese neuen Drachen kennenzulernen.", completion = "Nun gut! Wir sollten den Repräsentanten der Netherschwingen aufsuchen.\n\nEr heißt Mordenaku. Wie es scheint, ist er ebenfalls ein Prinz.", sourceObjectiveStatus = "unverified-source-field" }
quests[76461] = { id = 76461, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drakonische Diplomatie", description = "Ich vermute, Vyranoth könnte ebenfalls Interesse daran haben, neue Drachen für unsere Sache zu rekrutieren... aber sie muss noch davon überzeugt werden.\n\nUnd ganz zufällig kann ich sehr überzeugend sein.\n\nIch werde mit Vyranoth sprechen, und wenn sie sich entschieden hat, sich uns anzuschließen, treffen wir Euch in Valdrakken.", sourceObjective = "Sprecht mit Prinz Mordenaku bei der Konvergenz des Bittstellers in Valdrakken.", progress = "Die Netherschwingen sind ein faszinierender Schwarm.", completion = "Diese Gesuche erscheinen mir mehr als angemessen. Nichts Obskures, nichts Geheimes.\n\nIch bin fast schon enttäuscht.\n\nIch kann mich um eines davon kümmern, aber für den Rest benötige ich Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76462] = { id = 76462, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlensäuberung", description = "Diese Höhle ist angemessen. Sie hat einen guten Ausblick über das umliegende Land und ist gut zu verteidigen.\n\nAber ihr Zustand ist inakzeptabel.\n\nIch werde Euch mit einer Verzauberung belegen. Wenn Ihr Euch den kleineren Spinnen nähert, werden sie eingefroren, wodurch wir sie umsiedeln können. Die Kokons und größeren Spinnen werden wir... endgültiger behandeln müssen.\n\nKümmert Euch darum.", sourceObjective = "Säubert die Höhle über dem Sandverlorenem Sanktum in Thaldraszus von den Spinnen.", progress = "Seid Ihr fertig?", completion = "Ausgezeichnet, {class}. Wir können uns um den Rest kümmern und sie in eine andere Höhle bringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76463] = { id = 76463, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köstliche Köstlichkeiten", description = "Selbstverständlich werden wir uns um die Netherwelpen kümmern.\n\nAber uns könnten die Snacks ausgehen. Die Käfer hier in der Nähe schmecken den Kleinen ganz besonders gut.\n\nWürdet Ihr uns vielleicht ein paar saftige Käferteile bringen? Nur das Beste für unsere kleinen Schätze!", sourceObjective = "Sammelt 10 saftige Käferteile von saftigen Käfern in den Rubinlebensbecken an der Küste des Erwachens.", progress = "Die Welpen lieben diese Käferteile einfach.", completion = "Habt Dank, {name}. Die Welpen werden sie lieben!\n\nLiebe Güte. Erst die Obsidianwelpen und nun das?\n\nIch kann mein Glück kaum fassen, das zu erleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[76464] = { id = 76464, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Thorignir", description = "Die Thorignir von Sturmheim haben die Stärke und die Macht, uns bei der Verteidigung von Amirdrassil eine große Hilfe zu sein, aber sie müssen sich erst noch auf den Dracheninseln einfinden. Ich vermute, dass... Odyn sich in ihre Reise eingemischt hat.\n\nWir werden mit ihrer Matriarchin sprechen. Furorion hat mir gesagt, dass ihre Brut offen dafür ist, anderen und auch Eurer Art zu helfen.\n\nWir werden der Sache nachgehen.", sourceObjective = "Sprecht mit der Brutmutter der Thorignir.", progress = "Wir werden herausfinden, warum diese Brut von Sturmdrachen dem Ruf der Inseln nicht gefolgt ist.", completion = "Wie kann er es wagen, Drachen in ihrer Bewegungsfreiheit einzuschränken?!", sourceObjectiveStatus = "unverified-source-field" }
quests[76465] = { id = 76465, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenhaltung", description = "Erst stellt er sich gegen die Drachenheit, dann versklavt er die Drachen und verwehrt ihnen ihr Geburtsrecht.\n\nWir werden diese sogenannten \"Hallen der Tapferkeit\" aufsuchen, alle besiegen, die sich uns in den Weg stellen, und die Sturmdrachen aus ihrer Gefangenschaft befreien.\n\nFolgt mir.", sourceObjective = "Sprecht mit Vyranoth und schließt das Szenario \"Sturm auf die Hallen der Tapferkeit\" ab.", progress = "Wir werden diese Drachen befreien.", completion = "Die Thorignir sind fürs Erste frei vom Einfluss dieses vermaledeiten Hüters... hoffentlich für immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[76469] = { id = 76469, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Funke der Verwüsteten Lande", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
