quests[76504] = { id = 76504, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die aufgerüstete Denkkappe", description = "Die Kappe hat eine erstaunliche Funktion: Setzt sie auf und schon wisst Ihr, wo Ihr hingehen müsst! Üben wir es mal!\n\nDer Pfeil über mir zeigt einen Hinweis, der zu einem anderen Pfeil irgendwo in Valdrakken führt. Und DIESER Pfeil führt dann zu einem weiteren...\n\nFolgt einfach den Pfeilen, bis Ihr sie alle findet und damit auch den Preis am Ende!", sourceObjective = "Nutzt die aufgerüstete Denkkappe, um Klaudias Hinweise zu finden, und kehrt dann zu Klaudia Huhu zurück.", progress = "Ihr müsst die Kappe stets tragen, wenn Ihr über Geheimnisse nachdenkt. Ihr wisst schließlich nie, welche Frequenzen Ihr womöglich anzapft... oder wer Eure anzapft.", completion = "Gut gemacht! Jetzt seid Ihr ein wahrer Denkmeister!", sourceObjectiveStatus = "unverified-source-field" }
quests[76506] = { id = 76506, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dryadenfeuerübung" }
quests[76509] = { id = 76509, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Sande", description = "Beschreibung", completion = "Der Götze von Ohn'ahra verfügt über interessante Eigenschaften. Ich denke, damit können wir ein weiteres Objekt finden, das ich suche.\n\nNutzt ihn südlich von Azim in den Wandernden Sanden. Sucht damit nach Fragmenten der zeitverlorenen Tafel.\n\nWenn das Glück auf unserer Seite ist, findet Ihr alle ihre Teile und könnt sie zusammensetzen." }
