quests[76521] = { id = 76521, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Herz für Gripsi", description = "<Die robotische Kreatur ist wie wild auf Euch zugerannt, aber greift Euch nicht an.\n\nVielmehr mag sie Euch nicht mehr von der Seite weichen.\n\nAn der Seite ist das Wort \"Gripsi\" eingraviert.\n\nSoridormi ist sicher sehr daran interessiert.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück, nachdem Ihr den Zeitriss abgeschlossen habt.", progress = "Hallo, {name}. Was habt Ihr da?", completion = "<Soridormi seufzt.>\n\nDas Ding kann hierbleiben... fürs Erste.\n\n<Soridormi starrt Gripsi an.>\n\nIch nehme eigentlich keine Streuner auf.\n\n<Soridormi sieht Euch an und tätschelt Gripsi dabei gedankenverloren den Kopf.>\n\nIch habe keine Zeit für so was, aber Ihr könnt es erstmal hier lassen. Danke für den Hinweis.", sourceObjectiveStatus = "unverified-source-field" }
quests[76522] = { id = 76522, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Träumerei der Schlacht" }
