quests[76530] = { id = 76530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untote Einladung", description = "Wir brauchen Euch in Tirisfal, {name}. Kommt schnell.\n\nEs braut sich etwas vor den Ruinen von Lordaeron zusammen, und es sieht nicht gut aus. Ich erkläre Euch alles, wenn Ihr ankommt.", sourceObjective = "Meldet Euch bei Lilian Voss in den Ruinen von Lordaeron.", completion = "Danke, dass Ihr gekommen seid. Es gibt ein neues Problem.", sourceObjectiveStatus = "unverified-source-field" }
quests[76531] = { id = 76531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen auf den Dracheninseln, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[76532] = { id = 76532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angriff auf den Urquell", description = "Terro hat sein Leben gegeben, um den Traum zu schützen. Das heißt, wir müssen es zu Ende bringen.\n\nVyranoth sollte in der Lage sein, mit Lethka fertig zu werden, aber wir müssen Suzska finden.\n\nIch hoffe, Lethka hat sie nicht zuerst angegriffen. Wir sollten mit der Suche in der Nähe des Quells beginnen.\n\nTrefft mich dort, damit wir unsere Suche fortsetzen können.", sourceObjective = "Spioniert mit Buri den Urquell des Lebens aus.", completion = "Buri ist hier?", sourceObjectiveStatus = "unverified-source-field" }
quests[76533] = { id = 76533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brenzlige Beobachtungen", description = "<Das flackernde Hologramm sticht Euch im Grün der Landschaft sofort ins Auge.>\n\nEine kurze Inspektion des Gegenstands zeigt, dass es sich um eine Art Katalog handelt, den ein Hüter in seinem Zeitweg zurückließ. Er enthält Beobachtungen der Yaungol, Vorfahren der Tauren.\n\n<Soridormi ist sicher sehr daran interessiert.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück.\n\nBereitgestellter Gegenstand:", completion = "<Soridormi wischt mit der Hand durch die holografischen Projektionen der Yaungol, als Ihr ihr das Hütertagebuch überreicht.>\n\nFaszinierende Technologie! Nicht unähnlich der Technologie unserer Titanen.\n\nIch bin sicher, die Einträge sind spannend zu lesen. Ich werde den Katalog auf die Tische legen, falls Ihr neugierig seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[76536] = { id = 76536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotkammrally", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76537] = { id = 76537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotkammrally - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76538] = { id = 76538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotkammrally - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76544] = { id = 76544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieger des Ödlands", description = "<Dieses Buch ziert offenbar eine Art modifiziertes Symbol der Horde. Ihr erkennt es als das Symbol der Bluthorde wieder, das Euch bei den Zeitweg-Überfällen begegnet ist.\n\nSeltsam, dass es noch immer hier ist, obwohl der Überfall vorüber ist.\n\nDas Buch wurde offenbar von Blut getränkt, auch wenn es längst getrocknet ist.\n\nSoridormi ist sicher sehr daran interessiert.>", sourceObjective = "Nachdem Ihr den Zeitriss abgeschlossen habt, kehrt zu Soridormi im Tyrholdreservoir zurück.", completion = "<Ihr überreicht Soridormi das Buch und sie blättert es durch.>\n\nUnsere Welt befindet sich seit so langer Zeit im Krieg, nur die Aggressoren ändern sich.\n\nIhre Welt ist auch vom Krieg geplagt, nur kämpfen sie untereinander, wieder und wieder.\n\nEs wäre ein Leichtes, sie dafür zu verurteilen, doch unser beider Welten ertrinken im Blut.\n\n<Soridormi blickt wehmütig.>\n\nIch werde das Buch auf den Tisch legen, falls Ihr es lesen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76545] = { id = 76545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest in Valdrakken", description = "Habt Ihr gehört? Das Braufest hat es bis hierher geschafft! Ihr solltet auf dem Handwerkermarkt mit Bragdur Kampfbräu sprechen. Er kann Euch alles darüber erzählen.", sourceObjective = "Sprecht mit Bragdur Kampfbräu.", completion = "Seid Ihr auf ein Bier gekommen? Hah! Haben wir reichlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[76546] = { id = 76546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mantismethodik", description = "<Dieses Bernschwert blieb zurück, als Ihr einen der Mantis zurück durch einen Zeitriss stießt.\n\nIhr prüft kurz, ob es sicher ist, und packt es dann ein.\n\nSoridormi ist vielleicht daran interessiert.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück, nachdem Ihr den Zeitriss abgeschlossen habt.", completion = "<Soridormi dreht die Klinge in den Händen und hält sie gegen das Licht.>\n\nDas ist das erste Mal, dass ich eine Klinge aus reinem Bernstein sehe.\n\nSie ist deutlich robuster, als ich dachte, und ziemlich dicht.\n\nGuter Fund, {name}. Ich lege sie auf dem Tisch aus, falls Ihr sie Euch später noch mal ansehen wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76547] = { id = 76547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alles, was glänzt...", description = "<Nachdem Ihr kürzlich die Zeitanomalie in diesem Zeitweg besiegt habt, fällt Euch diese goldene Vase auf.\n\nSie weist deutliche Abnutzungsspuren auf, ob von der Zeit oder anderen Einflüssen. Ihr könnt die Details der Gravuren an ihren Rändern kaum erkennen.\n\nSo mitgenommen sie auch aussehen mag, strahlt sie immer noch ein warmes Licht aus, ein starker Kontrast zur kühlen Umgebung.\n\nSie sieht völlig fehl am Platze aus. Soridormi ist sicher sehr daran interessiert.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück.\n\nBereitgestellter Gegenstand:", completion = "<Soridormi wiegt die Vase in den Händen.>\n\nIhr habt sie am Gipfel der Eiskrone gefunden, ja?\n\nDas ist... merkwürdig.\n\nUnser Lichkönig war nicht gerade für seine goldene Ästhetik bekannt, insbesondere nicht im Tode.\n\nIch werde sie auf die Tische stellen. Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[76548] = { id = 76548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einem geschenkten Fisch...", description = "Murglgalgul!\n\nGlulmual, rluu glua ffrl wawawamual. Lalala!\n\nMowua ha mwaaay.\n\n<Murloc-Ich wedelt mit einem Fisch in </seinen:ihren> Händen. Es wirkt etwas übereifrig. Soridormi ist sicher sehr daran interessiert.>", sourceObjective = "Kehrt zu Soridormi im Tyrholdreservoir zurück, nachdem Ihr den Zeitriss abgeschlossen habt.", completion = "<Soridormi sieht Euch matt an, als Ihr den Fisch überreicht.>\n\nEin Fisch. Vielen Dank, {name}, das wäre doch nicht nötig gewesen.\n\n\n\nIch lege den Fisch zu den anderen Dingen, nachdem ich ihn zeitlich arretiere.\n\nMerkt Euch bitte für die Zukunft: Auf den Geruch von verfaulendem Fisch kann ich verzichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[76549] = { id = 76549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Träumend im Traum" }
quests[76550] = { id = 76550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klarsicht" }
quests[76551] = { id = 76551, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schatztauchen" }
quests[76552] = { id = 76552, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktvoll", description = "Während Ihr für Pedgi auf Schleimjagd wart, habe ich die Ermittler hier gefragt, wie wir wirklich helfen können.\n\nEs scheint, dass einige von ihnen in Zeitanomalien feststecken. Glücklicherweise habe ich dem Metronografen gerade ein paar temporale Aufwertungen verpasst. Das sollte den Ermittlern beim Synchronisieren helfen.\n\nWir müssen ihn erstmal ausprobieren. Und da ist wohl auch gerade jemand in der Nähe, der sich dafür anbietet.", sourceObjective = "Testet den verbesserten Metronografen.", progress = "Oh, ich habe gesehen, dass Pedgi Euch aufgefordert hat, den Zeitschleimschmutz für mich zu sammeln. Darum hatte ich nicht gebeten und den brauche ich auch nicht.\n\n<Melly stößt einen langen, leidvollen Seufzer aus.>\n\nWenigstens versucht er zu helfen.", completion = "Der Metronograf scheint wie vorgesehen zu funktionieren!\n\nSehr interessant, dass sich Temporalenergie und Musik so ähnlich sind. Ich frage mich, ob der bronzene Drachenschwarm dieses Thema je erforscht hat...\n\nTut mir leid, ich schweife ab. Helfen wir wieder Tempo. Mein nächster Gehaltsscheck hängt davon ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[76557] = { id = 76557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ohne Ehre", description = "Gut, die Brille sollte kalibriert sein. Sieht aus, als wäre der Zusammenflusspunkt direkt hier auf dem Vorsprung. Was wohl mit ihm geschehen ist?", sourceObjective = "Beobachtet die Szene aus der Vergangenheit.", progress = "Ich frage mich, was wir finden werden?", completion = "<Zenata blickt ernst in die Ferne.> \n\nStreitkräfte des Erdwächters verfolgen eine der ihren... Was sie wohl vorhatten?", sourceObjectiveStatus = "unverified-source-field" }
quests[76558] = { id = 76558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basiskontrolle" }
quests[76559] = { id = 76559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere Eulchen" }
quests[76562] = { id = 76562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grabeninstandhaltung" }
quests[76564] = { id = 76564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Werkzeuge der Drachentöter", description = "Wenn wir einen Drachen verfolgen, sollten wir doch am besten die Djaradin dafür einsetzen, oder?\n\nMal sehen, was wir finden können, {name}.", sourceObjective = "Findet die drei Abstimmungsrelikte.", progress = "Ohne diese Abstimmungsrelikte werden wir das Geheimnis nicht lösen können, {name}.", completion = "Aha! Gebt sie her, dann kalibriere ich Eure Brille.", sourceObjectiveStatus = "unverified-source-field" }
quests[76566] = { id = 76566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dryadengarten", sourceObjective = "Sprecht mit Ethidris Bachschutz im Wurzelbandrefugium.", completion = "Cenarius selbst hat Euch geschickt? Wunderbar. Wir können die Hilfe brauchen.\n\nWir müssen diese Dryadeneichel finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[76567] = { id = 76567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garstiger Garten", description = "Das Refugium wurde überrannt!\n\nDie Wurzeln des Weltenbaumes sind entlang dieses Gartens gewachsen, aber wie es scheint, fühlen sich die Wildtiere mit der Veränderung nicht wohl.\n\nHelft ihnen bitte, ihre rastlose Energie loszuwerden. Vielleicht können sie sich hier wieder entspannen, wenn sie ermüdet sind.", sourceObjective = "Ermüdet 8 Wildtiere im Wurzelbandrefugium.", completion = "Danke, {name}. Ich kann sehen, dass Ihr sie für den Moment beruhigt habt.\n\nDas ist nicht zum ersten Mal passiert, und wahrscheinlich auch nicht zum letzten Mal. Sind es nur die Wurzeln von Amirdrassil? Dieses Verhalten ist so seltsam...", sourceObjectiveStatus = "unverified-source-field" }
quests[76568] = { id = 76568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pinienmauspanik", description = "Seit der Garten in solchem Aufruhr ist, horten die Pinienmäuse hier Samen. Wichtige Samen. Samen, in die wir viel Zeit der Pflege und Ausbildung investiert haben.\n\nEin sanftes Schütteln reicht schon aus, damit sie die Samen fallen lassen. Beeilt Euch bitte, bevor sie noch mehr stibitzen!", sourceObjective = "Schüttelt 20 Saaten von Pinienmäusen im Wurzelbandrefugium hervor.", progress = "Normalerweise verteilen die Pinienmäuse die Samen im ganzen Traum und sorgen damit für Vielfalt und Wachstum. Es ist ein wunderschöner Kreislauf.\n\nWenn Ihr einige Stunden entbehren könnt, ich habe eine Lektion über die Migrationsgewohnheiten der Pinienmäuse vorbereitet.", completion = "Wie es aussieht, hat Dionaessa sich für Euch als Ausbilder entschieden.\n\n<Ethidris verzieht das Gesicht.>\n\nWundervoll. Einfach perfekt.", sourceObjectiveStatus = "unverified-source-field" }
quests[76569] = { id = 76569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Druidenwächterkonferenz", description = "Normalerweise würden die Druiden eines Dryadenrefugiums eine neugeborene Dryade anleiten, bis sie bereit ist, ihre Position zu übernehmen.\n\nLeider ist es schwer, eine Dryade von demjenigen zu trennen, auf den sie geprägt ist.\n\n<Ethidris seufzt und reibt sich die Augen.>\n\nDas hat sie sehr deutlich gemacht. Aber egal, erzählt mir von Euch. Vielleicht seid Ihr <ein ebenso fähiger Pfleger/eine ebenso fähige Pflegerin>, wie ich es gewesen wäre.", sourceObjective = "Sprecht mit Ethidris Bachschutz im Wurzelbandrefugium darüber, wie man eine Dryade aufzieht.", progress = "<Ethidris blickt Dionaessa stirnrunzelnd an.>\n\nNeben all den anderen Dingen, die gerade passieren, haben wir eine neue Dryade aufzuziehen.", completion = "Ihr stürzt Euch regelmäßig in den Kampf und löst Probleme. Manchmal Eure eigenen, manchmal die anderer.\n\nDas klingt nicht viel anders als meine Erfahrungen mit den Dryaden.\n\nIch glaube, Dionaessa wird es gut gehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76570] = { id = 76570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Familienangelegenheiten", description = "Ich wurde damit beauftragt, jedem Dryadensamen Wissen zu vermitteln. Dionaessa hat alle meine Lehren erhalten, aber sie ist ungeübt darin, sie anzuwenden.\n\nIhr scheint darin geübt zu sein, Aufgaben zu erfüllen, Ihr werdet Dionaessa schon zeigen, wie der Hase läuft.\n\nGleich außerhalb des Gartens verhält sich eine Gruppe Peitscher im Gewundenen Wald seltsam rastlos. Sammelt einige ihrer Herzen, damit wir herausfinden können, was passiert ist.", sourceObjective = "Sammelt 6 Peitscherherzen im Gewundenen Wald in der Nähe des Wurzelbandrefugiums.", progress = "Der Druide Bachschutz sagte mir, die Peitscher lauern ihrer Beute gerne auf.\n\nIch bin froh, dass diese es nicht tun. Das macht den Kampf aufregender!", completion = "Diese Herzen stinken furchtbar! Fast so schlimm wie diese Schotlinge mit den kleinen scharfen Zähnen...", sourceObjectiveStatus = "unverified-source-field" }
quests[76571] = { id = 76571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachstumserfahrung", description = "Dionaessas Verbindung zu Cenarius verleiht ihr die Fähigkeit, Pflanzen wachsen zu lassen, aber sie braucht Platz, um zu üben.\n\nDie aufgebrachten Wildtiere hier würden Euch im Weg stehen. Der Gewundene Wald in der Nähe bietet mehr Raum mit weniger Hufen.\n\n<Melyrine lächelt. Ihre Augen leuchten.>\n\nKeine Sorge, falls sie von einem Schotling vergiftet wird. Dryaden sind immun gegen Gift. Ihr nicht.", sourceObjective = "Helft Dionaessa, 3 Blumen im Gewundenen Wald wachsen zu lassen.", completion = "Wächter. Wenn die Schotlinge den Boden hier vergiften, dann müssen wir die große Überwucherung mit dem unfassbaren Gestank da drüben zurückschneiden!", sourceObjectiveStatus = "unverified-source-field" }
quests[76572] = { id = 76572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine giftige Beförderung", description = "<Wächter/Wächterin>! Diese Schotlinge haben die Peitscher vergiftet und jetzt haben sie diese Mandragora verderbt!\n\nWenn wir sie nicht aufhalten, wird sich das Gift in den Garten hinein ausbreiten. Das muss der Grund für diese Aufregung unter den Wildtieren im Garten sein. Eine Invasion stand kurz bevor!\n\nTöten wir sie. Das ist es, worauf Ihr mich vorbereitet habt... eine finstere Aufgabe!", sourceObjective = "Besiegt das krankhafte Wachstum im Gewundenen Wald.", completion = "Heda, Wächter! Ich habe mich noch nie lebendiger gefühlt als mit einem Speer in der Hand!\n\n<Dionaessa grinst über das ganze Gesicht.>\n\nDanke für Eure Führung!", sourceObjectiveStatus = "unverified-source-field" }
quests[76576] = { id = 76576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein unerwarteter Vorschlag", description = "Tuskarrartefakte unter der Erde, tief im Djaradingebiet?\n\nWenn wir dies nicht selbst gefunden hätten, würde ich es nicht glauben. Was, denkt Ihr, haben die hier unten gemacht?\n\nGut, der Nexuspunkt scheint direkt hier in der Höhle zu sein. Gehen wir der Sache auf den Grund!", sourceObjective = "Beobachtet die Szene aus der Vergangenheit.", progress = "Ich frage mich, was wir finden werden?", completion = "Tuskarr und Djaradin, die miteinander handeln? Ich frage mich, wie lange das gehalten hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[76577] = { id = 76577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest in Valdrakken", description = "Wir haben einige Braufestlieferungen auf die Dracheninseln geschickt. Ich habe gehört, dass sie eigene Feierlichkeiten organisiert haben! Natürlich sind die Feste hier unschlagbar, aber vielleicht lohnt es sich, den Drachen einen Besuch abzustatten!", sourceObjective = "Sprecht mit Bragdur Kampfbräu in Valdrakken auf den Dracheninseln.", completion = "Seid Ihr auf ein Bier gekommen? Hah! Haben wir reichlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[76578] = { id = 76578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rallye von Khaz Algar", description = "Rast durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Rast durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[76579] = { id = 76579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Braufest in Valdrakken", description = "Anscheinend veranstalten die Dracthyr dieses Jahr ihre eigenen Braufestfeiern! Sobald Ihr hier mit dem Feiern fertig seid, solltet Ihr auf die Dracheninseln reisen und sehen, was sie auf die Beine gestellt haben.", sourceObjective = "Sprecht mit Bragdur Kampfbräu in Valdrakken auf den Dracheninseln.", completion = "Seid Ihr auf ein Bier gekommen? Hah! Haben wir reichlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[76586] = { id = 76586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verbreitung des Lichts" }
quests[76587] = { id = 76587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschung: Zentauren der Ebenen von Ohn'ahra" }
quests[76588] = { id = 76588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verteidiger der Flamme", description = "Die Expeditionstruppen treffen auf starke Widersacher.\n\nKreaturen aller Arten werden von unseren Schlüsselflammen wie Motten angezogen und wollen ihr Licht auslöschen, was unsere Wiederaufbaubemühungen behindert.\n\nBitte helft uns, zwei der furchterregendsten Bewohner zu bezwingen, die unsere Schlüsselflammen bedrohen. Gemeinsam können wir sie in die Dunkelheit zurückdrängen.", sourceObjective = "Eliminiert zwei seltene Kreaturen in den Gebieten der Schlüsselflammen.", progress = "Habt Ihr die Bedrohungen ausgeschaltet?", completion = "Fantastische Arbeit, das sind zwei Bedrohungen weniger, um die wir uns kümmern müssen!", sourceObjectiveStatus = "unverified-source-field" }
quests[76591] = { id = 76591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schaumige Gebräue", description = "Verflixt! Es war womöglich ein Fehler, die Dracthyr um Hilfe bei diesen Lieferungen zu bitten. Sie haben die Bierfässer durch die Stadt gerollt und sie überall zertrümmert! Aber wir sollten das Bier nicht verschwenden, wenn wir etwas tun können!\n\nNehmt ein Fass und steigt in den Himmel auf! Versucht, so viel Bier zu retten, wie Ihr könnt, indem Ihr die Blasen sammelt.", sourceObjective = "Sammelt Gebräublasen in Valdrakken.", completion = "Vielen Dank für die Hilfe. Jetzt muss ich die Dracthyr nur noch überzeugen, die Fässer einfach herzufliegen, anstatt sie herumzurollen...", sourceObjectiveStatus = "unverified-source-field" }
quests[76592] = { id = 76592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein einzelner Flügel", description = "Amythora ist mit schlimmen Neuigkeiten zurückgekehrt. Die Splitterflammen bestehen weiter!\n\nWir haben versucht, unabhängige Gruppen von Dracthyr zu finden und sie hier in Valdrakken anzusiedeln. Ich habe Amythora und Marithos geschickt, um mit den letzten von ihnen zu sprechen, aber Amythora berichtet, dass es Überbleibsel der Splitterflammen sind.\n\nUnd sie haben Marithos gefangen genommen!\n\nDa er früher einer von ihnen war, könnte er in großer Gefahr schweben. Wir müssen nachsehen und für seine Sicherheit sorgen.", sourceObjective = "Sucht Marithos im Azurblauen Gebirge.", completion = "Er ist schwer verletzt, {name}, wir müssen ihm helfen!", sourceObjectiveStatus = "unverified-source-field" }
quests[76593] = { id = 76593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die besten Absichten", description = "Sie haben ihn nicht nur verprügelt... sie haben ihn auch gefesselt!\n\nUnd noch schlimmer ist... ich hätte wohl das Gleiche getan...\n\nWir werden Marithos nicht hier raustragen können, solange dieses Gewicht an ihn gekettet ist. Der Schlüssel muss irgendwo hier im Lager sein. Versucht, ihn zu finden, {name}, ich kümmere mich so lange um ihn.", sourceObjective = "Sucht nach dem Schlüssel zu Marithos' Fesseln in den Einsamen Fällen.", progress = "Wir müssen Marithos von seinen Fesseln befreien.", completion = "Ist das der Schlüssel, {name}? Gut. Befreien wir Marithos von diesen Fesseln. Dann können wir darüber nachdenken, was wir als Nächstes tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[76594] = { id = 76594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dracthyr am Boden", description = "Was Marithos angetan wurde, geht darüber hinaus, was einfache Heilung beheben kann. Wenn er hier hinausfliegen soll, wird er weitere Pflege brauchen.\n\nZum Glück gibt es in der Nähe Kräuter, die seine Heilung beschleunigen könnten... zumindest genug, dass er wieder stehen kann.\n\nSeht Euch um und sammelt etwas Schwingenblatt, {name}.", sourceObjective = "Sucht nach Schwingenblatt in den Einsamen Fällen.", progress = "Habt ihr dieses Schwingenblatt gefunden? Marithos wird ohne nicht fliegen können.", completion = "Danke, {name}. Hoffen wir jetzt auf das Beste...", sourceObjectiveStatus = "unverified-source-field" }
quests[76595] = { id = 76595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eiliges Abrücken", description = "Die Splitterflammen hier werden von Rüstmeister Doros' Tod nicht sehr erfreut sein...\n\nSie werden mich suchen kommen. Marithos und Amythora sind verwundbar. Wir können nicht zulassen, dass sie uns finden.\n\nSichert die Umgebung und haltet die Splitterflammen von Amythora und Marithos fern.", sourceObjective = "Haltet die Splitterflammen von Amythora und Marithos fern.", progress = "Wenn die Loyalisten der Splitterflammen uns finden, werden sie wohl keine Gefangenen machen.", completion = "Ich glaube, sie sind weg. Wir müssen hier raus. Sofort.", sourceObjectiveStatus = "unverified-source-field" }
quests[76597] = { id = 76597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf neuen Schwingen", description = "Ich bin froh, dass Schwingenfürst Dezran rechtzeitig ankam. Wenn nicht, wäre das... ganz anders ausgegangen.\n\nWir müssen Marithos nach Valdrakken zurückbringen, damit er sich erholen kann, aber sobald ich Dezran Bericht erstattet habe, werden wir einen Botschafter schicken, um sie wieder in unser Volk zu integrieren.\n\nSie haben gelitten. Wir haben gelitten. Vielleicht können wir jetzt alle genesen.\n\nFolgt mir zurück nach Valdrakken. Wir haben viel zu besprechen.", sourceObjective = "Sprecht mit Glutthal in Valdrakken.", completion = "Danke für eure Hilfe, {name}. Jetzt, da Dezran zurückgekehrt ist, können wir daran arbeiten, die Dracthyr endlich zusammenzubringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[76598] = { id = 76598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raue Kanten", description = "Bitte verzeiht, dass ich Euch nicht persönlich antreffe, {name}, doch diese Methode schien mir am schnellsten.\n\nUnser Krieg gegen die Primalisten hat unserer Königin seit jeher zugesetzt, aber in letzter Zeit scheint sie noch besorgter. Irgendetwas belastet sie. Ich weiß, wie schwer Kummer wiegen kann.\n\nSie hat Valdrakken vor einiger Zeit verlassen und sagte nur, dass sie einen ruhigen Ort zum Nachdenken suche, aber... Ich mache mir Sorgen.\n\nBitte, sucht nach ihr und vergewissert Euch, dass sie wohlauf ist. Sie muss nicht erfahren, dass ich Euch sandte.", sourceObjective = "Sucht Alexstrasza und seht nach ihr.", completion = "Es bekümmert mich mitanzusehen, welch finstere Tage Vyranoth durchmacht, doch ich habe noch Hoffnung, dass wir wieder zusammenstehen wie einst.\n\nIch habe sie vor Iridikron gewarnt. Mehr kann ich nicht tun.\n\nDer Rest liegt an ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[76599] = { id = 76599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau zwischen die Gyro-Optikmodule - Aktivieren" }
quests[76600] = { id = 76600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Genau zwischen die Gyro-Optikmodule", description = "Mein Mann Ezgi liebt diese Ernter, aber ich traue ihnen nicht, und jetzt wisst Ihr auch, warum!\n\nDie Lichter gehen aus, und sie wollen uns alle umbringen!\n\nWollt Ihr mir helfen, das zu regeln?\n\nIch bin eine Meisterschützin mit dem Gewehr. Ihr markiert das Ziel, und ich fange an zu schießen!", sourceObjective = "Eliminiert mit Auebrys Hilfe 8 dunkelwahnsinnige Ernter.", completion = "Ezgi wird zwar wütend sein, aber wir beide haben getan, was getan werden musste.", sourceObjectiveStatus = "unverified-source-field" }
quests[76733] = { id = 76733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erdäpfelernte", description = "Das Ernten in diesem Gebiet ist zu einer echten Herausforderung geworden. Die verrückt gewordenen Ernter vernichten den Großteil unserer Feldfrüchte, aber wer genau hinsieht, kann hier und da noch einige Kartoffeln erspähen.\n\nWenn Ihr die Erntefackeln entzündet, findet Ihr vielleicht noch ein paar Kartoffeln, die sich im Schatten verstecken.\n\nSammelt mit Hilfe dieser Fackeln so viele Kartoffeln wie möglich. In solch harten Zeiten sind wir um jede einzelne dankbar.", sourceObjective = "Entzündet 5 Erntefackeln und sammelt 15 Feuerscheinknollen.", progress = "Habt Ihr ein paar Knollen gefunden?", completion = "Die ist perfekt. Wir lieben gebratene Kartoffelspalten, wir werden heute Abend ein paar davon zubereiten!", sourceObjectiveStatus = "unverified-source-field" }
quests[76734] = { id = 76734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschung: Djaradin der Zaralekhöhle" }
quests[76735] = { id = 76735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anstieg von Reliktdiebstählen", sourceObjective = "In den Gasthäusern schnappt man jede Menge Gerüchte von irgendwelchen Möchtegerndieben auf, die es auf heilige Relikte abgesehen haben.\n\nIch habe die Aufsicht über die sichere Rückgabe der gestohlenen Waren an ihre rechtmäßigen Eigentümer. Wie ich höre, kann man auf Eure Hilfe vertrauen.\n\nBitte bringt diesen zeremoniellen Speer der Tuskarr zurück nach Iskaara. Und nehmt Euch vor Plünderern in Acht!", sourceObjectiveStatus = "unverified-source-field" }
quests[76739] = { id = 76739, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschung: Niffen der Zaralekhöhle" }
quests[76911] = { id = 76911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forschung: Drakoniden der Küste des Erwachens" }
quests[76982] = { id = 76982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sentinel's Summon", completion = "Danke, dass Ihr gekommen seid, {name}.\n\nLasst mich Euch die Situation erklären." }
quests[76983] = { id = 76983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zeitrisse" }
