quests[76993] = { id = 76993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schildkrötenkräfte" }
quests[76997] = { id = 76997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Schatten verloren", description = "Seid gegrüßt, {name}. Ich befinde mich in einer misslichen Lage. \n\nEin paar neue Rekruten und ich waren auf Patrouille in diesen Gefilden, als unsere Fackeln erloschen und wir uns völlig verirrten.\n\nIch habe in diesem Haus Zuflucht gefunden, aber die meisten Rekruten flohen orientierungslos in die Dunkelheit. \n\nHelft Ihr mir, sie zu finden? Ich habe noch eine Patrouillenfackel übrig. Ihr Anblick sollte genügen, um die Soldaten zu Euch zu führen.", sourceObjective = "Findet und versammelt 3 demoralisierte Rekruten mit der Patrouillenfackel.", progress = "Habt Ihr die Rekruten gefunden?", completion = "Die Zeit an Eurer Seite ist eine viel bessere Ausbildung als ich diesen Rekruten jemals bieten könnte. Einer von Ihnen wird hier bleiben, um Euch weiterhin zur Seite zu stehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77093] = { id = 77093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schattenflammenaxt", description = "In dem Moment, als Ihr versuchtet, Fyrakks Axt Fyr'alath zu benutzen, haben Euch die Flammen verschlungen. Offensichtlich war die Schattenflamme der Waffe zu intensiv.\n\nVielleicht solltet Ihr einen Experten für Schattenflammen und alte Artefakte konsultieren. Einer der Gelehrten im Archiv von Azeroth könnte womöglich eine Methode finden, wie man sie sicher handhaben kann.", sourceObjective = "Sucht das Archiv von Azeroth auf, um einen Experten für Schattenflammen zu finden.", completion = "Oh! Was haben wir denn hier? Wie außergewöhnlich!\n\nEinen Moment bitte...", sourceObjectiveStatus = "unverified-source-field" }
quests[77095] = { id = 77095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen auf den Dracheninseln, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77096] = { id = 77096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen auf den Dracheninseln, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77097] = { id = 77097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen auf den Dracheninseln, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77098] = { id = 77098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boden gewinnen", description = "Er braucht Heilung. Sofort.\n\nWir sind hier draußen zu ungeschützt. Die Anhänger der Splitterflammen könnten uns jederzeit überfallen.\n\nSuchen wir etwas Deckung, damit wir seine Wunden versorgen können.\n\nHaltet mir den Rücken frei!", sourceObjective = "Bringt Marithos sicher ins Azurblaue Gebirge.", completion = "Ihr habt Marithos allein hergebracht?\n\nDas war sehr riskant.\n\nAber Ihr habt recht. Marithos ist schwer verwundet, und wir haben nicht viel Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[77099] = { id = 77099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen auf den Dracheninseln, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77100] = { id = 77100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Untersuchung des Abhangs", description = "Nichts bringt einen besser in die Stimmung zum Graben wie eine steife Meeresbrise!\n\nWir stehen hier in den Ruinen eines uralten Fischerdorfes der Drachkin. Diese Drachkin waren die Vorfahren der blauen Drachkin, die heute auf der Insel leben. Es ist nicht unbedeutend, aber durch seine abgelegene Lage blieb es relativ unberührt von Schatzjägern.\n\nWenn es hier etwas gibt, das sich das Meer noch nicht geholt hat, werden wir es finden!", sourceObjective = "Sprecht mit Roska, um mit der Ausgrabung zu beginnen, und grabt dann Artefakte am Abhang aus.", completion = "<Roska pfeift beeindruckt.>\n\nWir haben dieses Freundchen gerade rechtzeitig gefunden, was? Hundert Jahre später, und er wäre Fischfutter!", sourceObjectiveStatus = "unverified-source-field" }
quests[77101] = { id = 77101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorlage: Zutatenquest", description = "Ricket hat die Botschaft geschickt, sie sei hier in Mechagon. Also bin ich sofort hierhergeeilt, um bei der, äh... Forschung zu helfen.\n\nIch habe die Peons auf der gesamten Insel nach jeglicher Technologie suchen lassen, die sie auftreiben konnten. Mit dem Zeug, das wir hier haben, werden wir ein paar erstaunliche Waffen herstellen, um gegen König Mechagon zu kämpfen. Danach werden wir reich, wenn wir sie verkaufen!\n\nHelft mir dabei, all die gesammelten Ideen in eine perfekte Waffe umzumünzen!", sourceObjective = "Helft Raketenchef Doppeldecker beim Bau der perfekten Waffe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77102] = { id = 77102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerhatz", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77103] = { id = 77103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerhatz - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77104] = { id = 77104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllenfeuerhatz - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77151] = { id = 77151, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Fass an der Klippe", description = "<Das Fass ist salzverkrustet und unter Schutt begraben, aber erstaunlich unbeschädigt.\n\nEs sieht nach einem alltäglichen Behälter aus, in dem die Dorfbewohner Waren gelagert haben, aber hier hat seit Tausenden von Jahren niemand mehr gelebt. Könnte da noch etwas drin sein?\n\nRoska will sich das bestimmt ansehen!>", sourceObjective = "Sprecht mit Roska, um damit zu beginnen, den Drachkinbehälter vorsichtig auszugraben.", completion = "Wow, {name}! Nicht nur ist dieses Lager intakt, es ist auch mit etwas anderem gefüllt als Meerwasser!\n\nStellt Euch vor, wir finden darin Urururomas Marmeladenrezept, das seit Tausenden von Jahren verloren war! Ja, die Leute hier werden das lieben!", sourceObjectiveStatus = "unverified-source-field" }
quests[77152] = { id = 77152, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen auf den Dracheninseln, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77153] = { id = 77153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen auf den Dracheninseln, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77154] = { id = 77154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Vorgeschmack der Vergangenheit", description = "Normalerweise versuchen wir, es zu vermeiden, Artefakte aufzubrechen. Aber ich glaube, in diesem Fall können wir mehr vom Inhalt über die Vergangenheit erfahren, als wenn wir nur ein versiegeltes Fass anstarren.\n\nAllerdings brauchen wir dazu erst die Genehmigung einer bestimmten Person. Immerhin geht es hier um ihre Geschichte. Ich glaube sogar, dass sie die einzige Person ist, die persönliches Interesse an diesem Fund haben könnte.\n\nIch werde das die Klippe hochbringen. Fragt Ihr doch Atrenosh Hagelstein, ob sie zusehen möchte, wie wir es aufbrechen.", sourceObjective = "Findet Atrenosh Hagelstein und fragt sie, ob sie den Behälter mit Euch öffnen möchte.", completion = "Deswegen machen wir das, was?\n\nDie Leute in Verbindung mit ihrer Vergangenheit zu bringen, ihnen das Gefühl zu geben, Teil von etwas Größerem zu sein. Es ist leichter, zu wissen, wohin man will, wenn man weiß, woher man kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[77155] = { id = 77155, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schankfass", sourceObjective = "Spendet an Tavernen auf den Dracheninseln, um die Rechnung zu begleichen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77156] = { id = 77156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botanische Umverteilung" }
quests[77159] = { id = 77159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich hoffe, das funghi-tioniert" }
quests[77163] = { id = 77163, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Späte Einsicht", description = "Sie scheinen zu wissen, dass Sarkareth fort ist, aber weil ihre Missionen sie so weit von der Zaralekhöhle fortgeführt haben, scheinen sie nie von seinem Tod gehört zu haben.\n\nWir sollten mit ihnen sprechen. Vielleicht würden sie wieder Schwarzschuppen werden, wenn sie wüssten, warum so viele ihrer Brüder und Schwestern mir jetzt folgen. Oder auch nicht...\n\n<Glutthal seufzt.>\n\nDas könnte katastrophal nach hinten los gehen, aber wir müssen es versuchen. Rüstmeister Doros scheint hier das Kommando zu haben. Sprecht mit ihm, {name}. Ich glaube nicht, dass er auf mich hören würde...", sourceObjective = "Konfrontiert Rüstmeister Doros in den Einsamen Fällen.", completion = "Das... lief nicht wie erhofft.", sourceObjectiveStatus = "unverified-source-field" }
quests[77164] = { id = 77164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scarab Test One" }
quests[77165] = { id = 77165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geheimnistuerischer Kontakt", sourceObjective = "Hallo, ich bin Reporter für das Auge von Azeroth.\n\nIch untersuche seltsame Aktivitäten in Valdrakken. Wollt Ihr helfen?\n\nIch habe eine Quelle, aber die spricht nur mit jemandem, der eine \"Denkkappe\" trägt. Angeblich hilft so eine Kappe, die Gedanken zu konzentrieren oder so was. Sei's drum, ich habe eine Liste der nötigen Komponenten zusammengestellt und dazu geschrieben, wo Ihr sie finden könnt.\n\nTreibt die Sachen auf, dann reden wir weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[77166] = { id = 77166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praxistest", description = "Nun, da Ihr wisst, wie man dieses Gerät benutzt, werden wir Eure Fertigkeiten testen.\n\nIch habe Euren Technoseher auf einen wertvollen Gegenstand abgestimmt, der irgendwo auf dieser Insel versteckt ist. Wenn Ihr ihn finden könnt, werden wir uns eine Szene aus der Vergangenheit ansehen, um herauszufinden, wie er dort hingekommen ist.\n\nZeit für Wissenschaft! Setzt... die Brille... auf! Sucht weiter!", sourceObjective = "Nutzt den Technoseher, um den versteckten Gegenstand zu finden.", progress = "Habt Ihr den versteckten Gegenstand gefunden, {name}?", completion = "Heureka! Geschafft!\n\nSchnell, gebt mir den Technoseher zurück. Wir müssen ihn für den nächsten Test neu einstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77169] = { id = 77169, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echsenkesseleskapade", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77170] = { id = 77170, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echsenkesseleskapade - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77171] = { id = 77171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echsenkesseleskapade - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77176] = { id = 77176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich kann durch die Zeit sehen!", description = "Gut, der Technoseher sollte kalibriert sein. Ich habe dieselben Einstellungen an meinem eigenen vorgenommen, damit wir dasselbe Phänomen beobachten können.\n\nSeid Ihr bereit? Setzt... ihn wieder... auf. Diesmal nutzen wir den Beobachtungsmodus.", sourceObjective = "Beobachtet Ereignisse der Vergangenheit.", progress = "Ich bin gespannt, was wir finden werden.", completion = "Ach je. Hahahaha!\n\nIch... hatte das ganz verdrängt. Ihr werdet Nirobin doch nichts davon erzählen, oder?\n\nAkademische Rivalitäten zeigen sich auf viele Arten. Das ist alles ganz harmlos, kann ich Euch versichern!", sourceObjectiveStatus = "unverified-source-field" }
quests[77178] = { id = 77178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taktischer Rückzug", sourceObjective = "Kehrt zu Alexstrasza im Zentrallager zurück.", completion = "Fyrakk ist also hinter dem Urquell her.", sourceObjectiveStatus = "unverified-source-field" }
quests[77191] = { id = 77191, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handhabung", description = "Wenn Ihr Fyr'alath sicher führen wollt, müsst Ihr den Waffenschaft mit drei Komponenten anpassen.\n\nZuerst braucht Ihr einen feuerfesten Balg, der die starke Hitze aushält. Beschafft Euch dann verzaubertes Pergament, das die volatile Magie der Waffe im Zaum halten kann. Und zuletzt muss ein Schreiber die richtigen Runen anbringen, damit Ihr die ersten beiden Materialien an die Axt binden könnt.\n\nIn meinem Tagebuch da drüben findet Ihr einige Empfehlungen zu Handwerkern, die Euch helfen können. Einige davon kennt Ihr vielleicht schon!", sourceObjective = "Erlangt einen symbiotischen Leuchtsporengriff, eine Rune der Schattenbindung sowie ein konzentriertes weises Pergament.", progress = "Sammelt die notwendigen Materialien bitte schnell. Ich will endlich anfangen.", completion = "Ausgezeichnet! Ich wusste, meine Anweisungen würden ausreichen!\n\nOh, und Glückwunsch an Euch. Ich bewundere Euren Fleiß.", sourceObjectiveStatus = "unverified-source-field" }
quests[77192] = { id = 77192, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine gehärtete Axt", description = "Vorbildlich. Einige der Komponenten können manuell angepasst und hinzugefügt werden, aber für den letzten Schritt benötigt man eine leistungsfähige Schmiede, um alle drei in der Flamme zu vereinen.\n\nIch habe mit Furorion gesprochen. Er kann Euch zu einer geeigneten Schmiede in der Obsidianzitadelle führen. Ich treffe Euch beide dort! Ich bin schon ganz gespannt, welche Ergebnisse mein genialer Plan hervorbringt!", sourceObjective = "Begebt Euch zur Obsidianzitadelle und bittet den Schmied, den Stiel mit der Axt zu verbinden.", progress = "Wir müssen den modifizierten Stiel am Axtkopf anbringen. Das ist gefährlicher, als es klingt...", completion = "Ihr müsst beweisen, dass Ihr der Verderbnis der Waffe widerstehen könnte.\n\nDas Ritual ist so weit. Ich kann Euch nach Aberrus bringen. Seid Ihr bereit zum Aufbruch?", sourceObjectiveStatus = "unverified-source-field" }
quests[77193] = { id = 77193, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Versuchung", description = "Nur um das klarzustellen: Wenn die Axt Euch bezwingt, bin ich verpflichtet, einzugreifen. \n\nAber das wird nicht passieren, oder? Ihr werdet nicht von der Schattenflamme verderbt werden. Ihr werdet Euch nicht in einen monströsen, mörderischen Schatten Eures früheren Ichs verwandeln. Ich werde nicht... eingreifen müssen.\n\nSolange wir uns darüber einig sind, wird niemand irgendwen töten müssen. Also dann, bringen wir es hinter uns.", sourceObjective = "Sprecht mit Furorion, um nach Aberrus zu reisen, und schließt das Szenario \"Entschlossenheit eines Helden\" ab.", progress = "Was für eine furchteinflößende Axt!", completion = "Wir haben jetzt etwas gemeinsam: Wir teilen die Last, aus dem Erbe meines Vaters etwas Positives zu machen.\n\nAber Ihr könnt Euch glücklich schätzen. Der Leidbringer liebt Gesellschaft. Schwingt die Axt mit Umsicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[77194] = { id = 77194, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für Knot!", progress = "Das Ding heißt Gordokfesselschlüssel... Na ja, zumindest nennen diese lustigen Gesellen ihn so. Vermutlich könnte jeder dieser Oger ihn haben, aber ich bin nicht sicher, ob ein bestimmter ihn trägt. Bei den Wachen wäre die Wahrscheinlichkeit vermutlich etwas größer...\n\nAch, was rede ich da, Ihr habt ihn schon längst, oder?! Ist er das da?!", completion = "Oh, danke, dass Ihr mich befreit habt! Ihr seid die Nummer Eins. Alle anderen: Nummer Zwei oder niedriger.\n\nIch wusste doch, dass ich zu mehr bestimmt bin, als auf dem Teller eines hungrigen Ogers zu landen!" }
quests[77195] = { id = 77195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachenperspektive", description = "Ich glaube, ich habe den perfekten Ort für den neuen Horst der Netherschwingen gefunden.\n\nDie Aussicht ist herrlich und die Lage ist recht abgeschieden.\n\nIch würde unseren Gästen gerne noch etwas von den Sehenswürdigkeiten Valdrakkens zeigen, bevor wir aufbrechen. Treffen wir uns dort?", sourceObjective = "Reist zur Höhle über dem Sandverlorenem Sanktum in Thaldraszus.", progress = "Die Aussicht an Höhle ist wirklich spektakulär.", completion = "Hier scheint es deutlich mehr Spinnen zu geben als bei meinem letzten Besuch.\n\nAber Vyranoth hat wohl einen Plan.", sourceObjectiveStatus = "unverified-source-field" }
quests[77197] = { id = 77197, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welpenschutz", description = "Gut gemacht, {name}.\n\nAls Nächstes müssen wir sichergehen, dass die Welpen der Netherschwingen ein anregendes Umfeld vorfinden, um aufwachsen und gedeihen können.\n\nLasst uns mit Mutter Elion sprechen. Ich bin mir sicher, dass sie die Gelegenheit, sich um die Welpen eines neuen Schwarms zu kümmern, mit Freude ergreifen wird.\n\nWürdet Ihr am Rubinlebensschrein zu uns stoßen?", sourceObjective = "Trefft Mutter Elion beim Rubinlebensschrein an der Küste des Erwachens.", completion = "Furorion hat mir mitgeteilt, dass wir bald neue Welpen hier erwarten dürfen?\n\nVon einem neuen Schwarm? Seid Ihr sicher, dass das kein Witz ist?\n\nNun gut. Dann wollen wir mal die Vorbereitungen dafür treffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77198] = { id = 77198, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerade recht zum Tee zu Hause", description = "Ich muss zugeben, ich habe nicht erwartet, die Zukunft meines Schwarms zu verändern, als ich ankam. Aber es fühlt sich an, als würden wir hier her gehören. Vielleicht ist das der Ruf, von dem sie gesprochen haben...\n\nWie auch immer, ich brauche Rast.\n\nFurorion sagte, er sei im Gerösteten Geißbock eingekehrt.\n\nKönnt Ihr uns dort treffen?", sourceObjective = "Trefft Euch mit Furorion, Mordenaku und Vyranoth im Gasthaus \"Zum Gerösteten Geißbock\" in Valdrakken.", progress = "Ich freue mich auf etwas Erholung.", completion = "Wir haben es Euch zu verdanken, dass die Sicherheit und die Zukunft meines Schwarms garantiert ist.\n\nVon der Scherbenwelt nach Azeroth zu reisen, war eine überwältigende Erfahrung, aber im besten Sinne des Wortes.\n\nDie Netherschwingen blicken der Erkundung dieser Welt mit Freuden entgegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77200] = { id = 77200, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Opfergaben für den Brunnen", description = "Amirdrassil wurde von den Bewohnern des Traums in diese Welt gebracht. Jetzt müssen wir sicherstellen, dass seine Wurzeln in den Wassern von Elune getränkt werden, indem wir einen neuen Mondbrunnen erschaffen.\n\nSo viele meines Volkes haben uns zu diesem Moment gebracht. Jeder sollte einen Anteil an dieser Einweihung haben.\n\nGeht, sprecht mit den hier versammelten Kaldorei und fragt sie, ob sie Opfergaben für die Zeremonie haben.", sourceObjective = "Sammelt Opfergaben von Nachtelfen im Zentrallager.", progress = "Habt Ihr alle Opfergaben für die Zeremonie gesammelt?", completion = "Jeder Kaldorei versteht die Trauer und das Hochgefühl eines solchen Moments. Den Schmerz, den wir ertragen haben, und die Hoffnung, die wir für die Zukunft haben.\n\nDiese Opfergaben sind entscheidend und werden geschätzt.", sourceObjectiveStatus = "unverified-source-field" }
quests[77201] = { id = 77201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine persönliche Opfergabe", sourceObjective = "Sprecht mit Tyrande Wisperwind im Zentrallager, um eine Opfergabe zu wählen.", progress = "Seid Ihr Euch Eurer Opfergabe sicher?", completion = "Eine bewundernswerte Wahl. Möge Elune Euren Weg erleuchten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77202] = { id = 77202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Bewahrung", description = "Willkommen, <Abenteurer/Abenteurerin>. Habt Ihr schon gehört?\n\nSeit die Gerüchte von Schätzen und geheimen Verstecken die Runde machen, wurden jede Menge Artefakte gestohlen.\n\nWenn Ihr mehr darüber erfahren wollt, sprecht mit Bewahrerin Kathos. Euer Geschick beim Entschlüsseln von Geheimnissen könnte hilfreich sein, um aufzudecken, wer hinter dem ganzen Chaos steckt.", sourceObjective = "Sprecht mit Bewahrerin Kathos im Gerösteten Geißbock in Valdrakken.", completion = "Ein neuer Rekrut? Wunderbar! Es gibt viel zu tun und zahlreiche Geheimnisse aufzudecken.\n\nSeid Ihr bereit, loszulegen?", sourceObjectiveStatus = "unverified-source-field" }
quests[77203] = { id = 77203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raritäten bewahren", description = "Entwirren wir ein Geheimnis! Macht Euch bereit für die kniffligsten Rätsel...\n\nSprecht mich wieder an, wenn Ihr bereit seid, Euch auf den Pfad der Bewahrung zu begeben.", sourceObjective = "Sprecht mit Bewahrerin Kathos, um ein Geheimnis zu beginnen, und gebt ihr Bescheid, wenn Ihr es gelöst habt.", progress = "Das Mysterium löst sich nicht von allein!", completion = "Ihr habt das \"Mysterium\" entschlüsselt und das Artefakt geborgen!\n\nAls guter Bewahrer solltet Ihr immer danach streben, Artefakte noch besser zu bewahren. Wenn Ihr etwas Neues entdeckt, wird sich sicher ein praktischer Nutzen dafür finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[77205] = { id = 77205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schergratschererei", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77206] = { id = 77206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schergratschererei - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77207] = { id = 77207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schergratschererei - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77208] = { id = 77208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fasslieferung", description = "Wenn Ihr nach Bier sucht, davon haben wir mehr als genug! Oder zumindest hätten wir das, wenn diese Valdrakkener sich endlich beeilen würden, den Rest der Fässer herzubringen.\n\nWir haben unser Braufestbräu hergeschickt, damit sie feiern können. Und kaum zu glauben, aber sie haben schon ihre eigenen Traditionen gegründet! Fässer durch die Stadt rollen? So geht man doch nicht mit einem guten Gebräu um!\n\nWürdet Ihr mir zur Hand gehen und diese Fässer herbringen? Versucht nur, sie nicht kaputt zu machen!", sourceObjective = "Liefert Fässer zum Handwerkermarkt in Valdrakken.", progress = "Vorsichtig mit den Fässern! Gutes Bier sollte man nicht so durchschütteln.", completion = "Ich bin froh, diese Lieferung wohlbehalten zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[77209] = { id = 77209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saatvermächtnis", description = "Ich habe jahrelang mit Denalan in Teldrassil gearbeitet. Seine Forschung wird die Grundlage für die Wiederherstellung dieser Saaten sein.\n\nAls ersten Schritt müssen wir sie wieder zum Leben erwecken, damit sie zu gesunden, blühenden Pflanzen heranwachsen können. Ich habe einige passende Flecken Erde in der Nähe gesehen, wo die Pflanzen Wurzeln schlagen und wachsen können, was ihr wahres Potenzial entfesseln wird.\n\nWie werden einen kleinen, einen prallen und einen gigantischen Samen pflanzen und beobachten, wie die Qualität der Saat das Wachstum beeinflusst.", sourceObjective = "Pflanzt einen Samen in jedem Flecken Traumboden.", progress = "Habt Ihr die Samen ausgebracht?", completion = "Denalan wäre stolz zu sehen, dass jemand wie Ihr seine Arbeit fortführt!", sourceObjectiveStatus = "unverified-source-field" }
quests[77231] = { id = 77231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Technosehen für Anfänger", description = "Durch eine annähernd perfekte Verbindung von Technik und arkaner Verzauberung habe ich einen Weg entwickelt, die psychometrischen Eigenschaften von Gegenständen zu analysieren. Wenn Ihr diese Brille tragt, könnt Ihr die Daten als dynamische Simulakren sehen!\n\nSimpel, oder? Ich nenne sie Psychometrisches Audio-Visuelles Diskretes Wellenanalyse- und Sichtungsgerät! Für den Laien nennen wir sie \"Technoseher\". Markenzeichen und Patent angemeldet.\n\nHier, probiert es aus!", sourceObjective = "Lernt, den Technoseher zu benutzen.", progress = "Ich habe Euch den Technoseher gegeben. Bitte! Setzt ihn auf!", completion = "Gut gemacht!\n\nIch muss zugeben, eine Brille aufzusetzen, ist nicht gerade schwer, aber trotzdem! Ihr habt es geschafft!", sourceObjectiveStatus = "unverified-source-field" }
quests[77236] = { id = 77236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zeit heilt alle Risse", description = "Wir müssen Risse schließen. Wir müssen Zeitwege reparieren. Ehrlich gesagt können wir gerade jede Hilfe brauchen.\n\nEs gibt immer Neues zu tun. Seid Ihr für die nächste Herausforderung bereit?", sourceObjective = "Schließt einen Zeitriss, indem Ihr eine Gebrochene Kausalität besiegt.", progress = "Na los, diese Risse schließen sich nicht von allein.", completion = "Gute Arbeit da draußen.\n\nGönnt Euch ruhig eine kleine Verschnaufpause, aber haltet Eure Waffen griffbereitet. Zuletzt kamen die Überraschungen Schlag auf Schlag.\n\nZum Glück ist die harte Arbeit jede Mühe wert. Mit jedem geschlossenen Zeitriss kommen wir einen Schritt näher, die Zeitwege zu reparieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[77237] = { id = 77237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unvollendete Denkkappe", description = "<Bringt die unvollendete Denkkappe zu Klaudia Huhu nahe des Barbiers in Valdrakken.>", sourceObjective = "Bringt die unvollendete Denkkappe zu Klaudia Huhu in Valdrakken.", progress = "<Klaudia sieht Euch an, aber sagt nichts.>", completion = "<Klaudia deutet auf Euren Kopf, dann auf Ihren. Sie gestikuliert nach Euer unvollendeten Denkkappe.\n\nMit einem Bogenlichtschraubenschlüssel macht sie sich an den Kabeln und Linsen zu schaffen und legt schließlich einen Schalter um. Die Denkkappe schaltet sich surrend ein.\n\nKlaudia gibt sie Euch zurück.>", sourceObjectiveStatus = "unverified-source-field" }
quests[77238] = { id = 77238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telaartrauma", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77239] = { id = 77239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telaartrauma - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77240] = { id = 77240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telaartrauma - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77241] = { id = 77241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine vorhersehbare Freundschaft", sourceObjective = "Ich habe hohe Erwartungen an Euch. Ich weiß, dass wahre Größe in Euch steckt.\n\nMacht weiter so.", sourceObjectiveStatus = "unverified-source-field" }
quests[77242] = { id = 77242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele Geißelsteine des Eindringlings", progress = "Ein Geißelstein des Eindringlings war das Insigne der Elitetruppen der Geißel. Man fand sie manchmal bei den stärkeren Kämpfern der Truppen, die in Stratholme und Scholomance stationiert waren.\n\nIch habe früher Ehrenmarken dagegen eingetauscht. Ich bezweifle zwar, dass Ihr je wieder welche findet, aber wenn doch, bringt diese bitte sofort zu mir, damit ich sie vernichten lassen kann.", completion = "Jeden Tag tauchen weitere Geißelsteine auf, {name}, von Euch und immer mehr anderen Abenteurern.\n\nZum Glück sind keine unserer Soldaten unerklärlicherweise verschwunden, und ich habe auch nicht mehr markerschütternde Schreie gehört, als für diese Gegend normal ist.\n\nIch würde an Eurer Stelle lieber nicht fragen. Hier ist Eure Belohnung." }
quests[77243] = { id = 77243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele Geißelsteine des Verderbers", progress = "Ein Geißelstein des Verderbers war das Insigne der Oberanführer der Geißel. Mächtige Wesen, die einst eine hohe Position in der Geißel bekleideten, besaßen stets einen.\n\nIch habe früher Ehrenmarken dagegen eingetauscht. Ich bezweifle zwar, dass Ihr je wieder welche findet, aber wenn doch, bringt diese bitte sofort zu mir, damit ich sie vernichten lassen kann.", completion = "Jeden Tag tauchen weitere Geißelsteine auf, {name}, von Euch und immer mehr anderen Abenteurern.\n\nZum Glück sind keine unserer Soldaten unerklärlicherweise verschwunden, und ich habe auch nicht mehr markerschütternde Schreie gehört, als für diese Gegend normal ist.\n\nIch würde an Eurer Stelle lieber nicht fragen. Hier ist Eure Belohnung." }
quests[77244] = { id = 77244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele Geißelsteine des Verderbers", progress = "Ich muss Euch wohl kaum die ganze Tirade über Geißelsteine runterbeten, {name}, also komme ich gleich zur Sache. Ich bin SEHR interessiert daran, meine Sammlung zu erweitern, und Ihr seid SEHR an dem Zeug interessiert, das ich anzubieten habe.\n\nGeißelsteine des Verderbers sind bei Weitem am mächtigsten, also kommen wir ins Geschäft, wenn Ihr auch nur ein paar habt.\n\nUnd sagt der Argentumdämmerung nichts davon! Das ist unser kleines Geheimnis, alles klar?", completion = "Und noch eine Ladung Geißelsteine von meinem besten Kumpel, {name}! Ich danke Euch erneut. Die passen perfekt zu meinem restlichen Lager. Macht weiter so, dann muss ich mir ein neues Lager suchen!\n\nHier, das ist für Eure Mühen. Ich mag dieses kleine Tauschgeschäft, dass wir hier spielen. Machen wir weiter so.\n\nAber nein, ich werde Euch immer noch nicht sagen, was ich damit mache." }
quests[77245] = { id = 77245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Viele Geißelsteine des Eindringlings", progress = "Ich muss Euch wohl kaum die ganze Tirade über Geißelsteine runterbeten, {name}, also komme ich gleich zur Sache. Ich bin SEHR interessiert daran, meine Sammlung zu erweitern, und Ihr seid SEHR an dem Zeug interessiert, das ich anzubieten habe.\n\nGeißelsteine des Eindringlings sind ziemlich leicht zu finden, also müsst Ihr mir eine ganze Menge bringen.\n\nUnd sagt der Argentumdämmerung nichts davon! Das ist unser kleines Geheimnis, alles klar?", completion = "Und noch eine Ladung Geißelsteine von meinem besten Kumpel, {name}! Ich danke Euch erneut. Die passen perfekt zu meinem restlichen Lager. Macht weiter so, dann muss ich mir ein neues Lager suchen!\n\nHier, das ist für Eure Mühen. Ich mag dieses kleine Tauschgeschäft, dass wir hier spielen. Machen wir weiter so.\n\nAber nein, ich werde Euch immer noch nicht sagen, was ich damit mache." }
quests[77248] = { id = 77248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Erkennen von Talent", sourceObjective = "Eure Erfolge sind beeindruckend.\n\nBitte nehmt dies als kleines Zeichen unserer Wertschätzung. So könnt Ihr unsere Farben tragen, während Ihr die Zeitwege wiederherstellt.", sourceObjectiveStatus = "unverified-source-field" }
quests[77249] = { id = 77249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jetzt gehört Ihr zu uns", sourceObjective = "Vielleicht könnt Ihr jetzt das Gesamtbild sehen. Tollkühne Zeitreisen können Konsequenzen haben, und die Schäden an den Zeitwegen sind immens.\n\nWie Ihr seht, ist die Zeit wie ein gewundener Strang. Ihr habt schon viele Fäden entwirrt und von Euren Mühen profitieren wir alle. Ihr habt echtes Heldentum bewiesen - nicht nur auf dieser Welt, sondern auf vielen anderen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77250] = { id = 77250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entfaltetes Potenzial", sourceObjective = "Wie ich höre sind die Bewohner anderer Zeitwege voll des Lobes für Euch. Ihr seid nicht nur in dieser Welt ein wahrer Held. Auch in anderen Dimensionen spricht man Euren Namen mit Ehrfurcht aus.\n\nSeid Ihr sicher, dass Ihr kein Bronzedrachen seid?\n\nNur ein Scherz. Vielen Dank, {name}. Ohne Euch hätten wir es nie geschafft.", sourceObjectiveStatus = "unverified-source-field" }
quests[77251] = { id = 77251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Traumsprung formen", description = "Der Smaragdgrüne Traum vibriert vor Energien, wie ich es seit Ewigkeiten nicht mehr gespürt habe.\n\nEin Teil dieser Energien dringt sogar durch die Barriere zwischen dem Traum und Azeroth hindurch und verschmilzt zu einem schimmernden pollenartigen Pulver.\n\nSammelt so viel davon, wie Ihr könnt. Wir haben so etwas noch nie zuvor gesehen!", sourceObjective = "Sammelt Traumsprungvereinigung in der Nähe des Traumsprungs.", progress = "Die Partikel der Traumessenz funkeln im Wind, der sie über das Land verteilt.", completion = "Danke, {name}. Das wird uns helfen, die Wunder zu verstehen, die wir beobachten.", sourceObjectiveStatus = "unverified-source-field" }
quests[77254] = { id = 77254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützt das Abkommen: Zeitriss", description = "Der Bronzene Drachenschwarm hat lange im Verborgenen operiert, um Zeitanomalien so schnell zu beheben, wie sie nur auftauchen. Wie es scheint, sind die Anomalien in letzter Zeit aber etwas zu groß geworden.\n\nHier kommt Ihr ins Spiel.\n\nSoridormi leitet gerade östlich von Valdrakken die Bemühungen, einige besonders garstige Zeitrisse zu kitten. Unterstützt sie, wie auch immer sie es für nötig hält.", sourceObjective = "Reist zum Tyrholdreservoir und unterstützt Soridormi darin, einen Zeitriss auszuräumen. Führt Eure Bemühungen fort, dem Valdrakkenabkommen und seinen Verbündeten auf den ganzen Dracheninseln zu helfen.", completion = "Die Arbeit der Bronzenen ist nie vollendet, hab ich recht?\n\nBitte nehmt dieses bescheidene Geschenk an, zusammen mit unserem aufrichtigen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[77260] = { id = 77260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messerdornhöhenhast", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77261] = { id = 77261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messerdornhöhenhast - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77262] = { id = 77262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Messerdornhöhenhast - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77263] = { id = 77263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Fackel von Pyrreth", description = "Beginnen wir mit einem einfachen Test.\n\nIch habe ein Artefakt irgendwo in der Rubinenklave versteckt.\n\nWenn Ihr die Fackel hervorgeholt habt, sollte sie aufleuchten, sobald Ihr Euch dem Ziel nähert. Und wenn meine Theorie stimmt, sollte sie mit dem Schloss interagieren, das ich am Artefakt angebracht habe.\n\nBringt mir zurück, was sich darin befindet. Alles klar?", sourceObjective = "Nutzt die Fackel der Öffnung, um Kathos' Artefakt aufzuschließen, das in der Rubinenklave versteckt ist.", progress = "Kommt zurück, wenn Ihr geborgen habt, was ich suche.", completion = "Ah, da ist ja mein Feldstecher. Ich muss ihn versehentlich hineingelegt haben.\n\nUnd dann habe ich das Ding nicht mehr aufbekommen. Aber Euch ist es gelungen!\n\n Vielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[77264] = { id = 77264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoundreh", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
