quests[77266] = { id = 77266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auchindoundreh - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77267] = { id = 77267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ausgrabungen für Anfänger", description = "Ihr wollt also lernen, wie man Artefakte ausgräbt? Da seid Ihr zur richtigen Orcin gekommen!\n\nWie sich herausstellt, ist es sehr nützlich, Erde formen zu können, wenn man Dinge aus dem Boden holen will. Und wenn man bedenkt, wie sehr die Elemente unsere Arbeit beeinflussen, kann es nie schaden, einen Elementar dabeizuhaben.\n\nAber man muss kein Schamane sein, um Ausgrabungen zu meistern. Ich kümmere mich um die Elemente. Lasst mich Euch die Feinarbeit erklären.", sourceObjective = "Trefft Euch draußen mit Roska, um mehr über Ausgrabungen zu lernen.", progress = "Was denkt Ihr? Habt Ihr Spaß?", completion = "Das ist mal ein Fund! Schau einer an. Ihr seid ein Naturtalent.", sourceObjectiveStatus = "unverified-source-field" }
quests[77268] = { id = 77268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Praxiserfahrung", description = "Gute Arbeit mit diesem kleinen Fund! Seid Ihr jetzt bereit für etwas Größeres?\n\nDie kleinen Sachen auszugraben, bringt oftmals etwas viel GRÖSSERES unter der Oberfläche zum Vorschein. Wenn wir noch ein wenig mehr Erde aufwühlen, steht uns ein großer Fund bevor, da bin ich sicher.\n\nDie Arbeitsweise bleibt bei einem großen Fund fast dieselbe, es gibt nur ein paar Schritte mehr. Warum versucht Ihr das nicht auch? Das wäre eine gute Übung für Euch.\n\nKeine Sorge! Ich kann Euch anleiten.", sourceObjective = "Fördert den großen Fund zutage, dann sprecht mit Roska, um ihn auszugraben.", completion = "Seht Euch an, Meisterausgräber! Ich schätze, Ihr seid bereit für echte Feldarbeit.\n\nWir sehen uns im Staub!", sourceObjectiveStatus = "unverified-source-field" }
quests[77276] = { id = 77276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garona, übernehmen Sie", description = "Klaudia Huhu sagt, sie hätte eine Theorie, wer die Artefakte stiehlt.\n\nSucht sie wieder nahe des Barbiers auf.", sourceObjective = "Sprecht mit Klaudia Huhu am Barbier von Valdrakken.", completion = "Ich habe eine Theorie. Was, wenn diese sogenannte \"Bewahrerin\" die Artefakte stiehlt, nur damit Ihr dann Fälschungen davon zurückbringt?\n\nIch gebe Euch die Koordinaten für einen Kasten, in dem die Bewahrerin die Artefakte aufbewahrt. Nehmt eins und folgt diesen Koordinaten zu einem Gutachter, der die Echtheit des Fundes verifizieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[77277] = { id = 77277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bewahrte Unschuld", description = "Bringt den Gegenstand zurück, bevor die Bewahrerin sein Fehlen bemerkt.\n\nBerichtet Klaudia dann, dass ihre Theorie sich nicht bewahrheitete.", sourceObjective = "Bringt das Grabesbanner zurück zur Kiste der Bewahrerin im Gerösteten Geißbock.", completion = "Wirklich? Und ich war so sicher, dass sie die Strippenzieherin hinter der ganzen Sache wäre...\n\nNa ja, ich habe noch andere Spuren zum Weiterverfolgen. Ich sag Euch Bescheid, wenn ich etwas Handfestes habe.\n\nGebt mir auch den Schlüssel zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[77278] = { id = 77278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feger der Festung der Stürme", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77279] = { id = 77279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feger der Festung der Stürme - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77280] = { id = 77280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feger der Festung der Stürme - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77281] = { id = 77281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakt sicherstellen", sourceObjective = "Ein Kollege der Bewahrerin hat diese Notiz dagelassen.\n\nOffenbar bedrohen die Primalisten das Konservatorium der Lebensbinderin und ein Artefakt ist in Gefahr. Bitte spürt es auf und stellt es sicher, bevor diese Plünderer es sich unter den Nagel reißen.\n\nDie Koordinaten aus der Notiz sollten mit Eurer seltsamen \"Denkkappe\" funktionieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[77282] = { id = 77282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Artefakt sichergestellt", description = "<Wenn Ihr die Fackel zurück zu Bewahrerin Kathos bringt, erfahrt Ihr vielleicht, wie sie funktioniert.>", sourceObjective = "Bringt die Fackel von Pyrreth zurück zu Bewahrerin Kathos in Valdrakken.", progress = "Willkommen zurück, Abenteurer. Habt Ihr etwas gefunden?", completion = "Ihr habt die Fackel von Pyrreth gefunden! In den Archiven gibt es Geschichten darüber. Ihr sagt, die Bewahrerin ließ danach entsenden?\n\nEs heißt, die Fackel kann alte Apparaturen aktivieren und leuchtet auf, wenn sie sich in der Nähe anderer Artefakte befindet. Ich habe eine Möglichkeit, um es zu testen.\n\nHier, nehmt Ihr die Fackel und passt gut darauf auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[77283] = { id = 77283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Schlacht an mehreren Fronten", description = "Die Kaldorei haben unter den Ästen von Amirdrassil einen provisorischen Stützpunkt errichtet.\n\nMit Hoffnung und harter Arbeit wird dieses Lager dauerhaft werden, wenn der Baum unsere Welt betritt. \n\nMacht Euch mit den vorhandenen Vorräten vertraut. Dann kehrt zu mir zurück.", sourceObjective = "Trefft Saelienne im Zentrallager.", progress = "Habt Ihr hier im Lager gefunden, was Ihr braucht?", completion = "Tyrande ist aufgebrochen, um die Druiden der Flamme zu untersuchen, mehr über ihren Zweck im Smaragdgrünen Traum zu erfahren und ihre Anführer zu identifizieren.\n\nWie konnten sich Nachtelfen und Bewohner des Traums der Flamme zuwenden?\n\nIch bin zuversichtlich, dass Ihr und Tyrande die Antwort finden werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[77284] = { id = 77284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein frostiger Aufstieg", sourceObjective = "Im Gemischtwarenladen gibt es einen Verkäufer, der immer eine gute Quelle für heiße Gerüchte ist.\n\nEr hat mir von einer Expedition nach Vakthros im Azurblauen Gebirge berichtet. Klingt so, als wäre jemand auf der Suche nach jener Fackel, die Ihr gefunden habt.\n\nNa jedenfalls hat der Verkäufer einen Blick auf ihre Karte erhascht und sich prompt einige Koordinaten davon notiert. Hoffentlich bringt Euch das auf die richtige Fährte.", sourceObjectiveStatus = "unverified-source-field" }
quests[77286] = { id = 77286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein kundiger Abstieg", description = "<Die Durchschrift ist in einer uralten Sprache. Vielleicht kann Bobby Carlisle den Text übersetzen lassen.>", sourceObjective = "Bringt das Abpausbild der enthüllten Tafel zu Bobby Carlisle in Valdrakken.", progress = "Habt Ihr etwas gefunden?", completion = "Ihr habt jemanden gefunden, der dort gefangen war? Und die anderen waren tot? Ein Glück hattet Ihr diese Fackel!\n\n<Bobby schaut sich die Radierung an.>\n\nIch erkenne den Text nicht, aber ich werde ihn Bewahrerin Kathos zeigen. Hoffentlich hilft uns der Inhalt herauszufinden, worauf es diese Gruppe abgesehen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[77303] = { id = 77303, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Götzensuche", sourceObjective = "Es kam gerade noch eine Nachricht von Kathos an.\n\nDarin steht, dass ein Artefakt bedroht ist, das in einem der Grabeshügel der Ewigen Kurgane versteckt liegt. Außerdem heißt es, dass uralter Weihrauch das Artefakt vor Außenseitern verbirgt.\n\nDie restlichen Informationen stehen in der Nachricht. Viel Glück, Abenteurer!", sourceObjectiveStatus = "unverified-source-field" }
quests[77304] = { id = 77304, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Götze in der Hand", description = "<Beim Götzen scheint es sich um eine Figur von Ohn'ahra aus Serevit zu handeln. Dieses Erz wird in vielen titanischen Tempeln verwendet.\n\nBewahrerin Kathos ist sicher sehr daran interessiert.>", sourceObjective = "Bringt den Götzen von Ohn'ahra zu Bewahrerin Kathos in Valdrakken.", progress = "Was habt Ihr herausgefunden?", completion = "Ihr habt den Götzen von Ohn'ahra gefunden! Ich sollte wohl nicht so überrascht sein.\n\nWir müssen Artefakte wie dieses an ihren rechtmäßigen Platz zurückbringen. Aber wenn meine Vorgesetzten recht haben, würden wir dadurch riskieren, dass sie in die falschen Hände geraten.\n\nLasst mich den Götzen untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77305] = { id = 77305, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus den Sanden", description = "<Die zeitverlorenen Fragmente wurden zu einer Steintafel zusammengesetzt, aber die Inschrift ist größtenteils abgegriffen und unvollständig.\n\nBewahrerin Kathos will sie sicher untersuchen.>", sourceObjective = "Bringt die unvollständige Tafel zu Bewahrerin Kathos.", progress = "LINDE! Wie ist es Euch in den Wandernden Sanden ergangen? Habt Ihr die Tafelfragmente gefunden?", completion = "Ah, ja, ich kann einen Teil der Tafelinschrift erkennen. Einige Teile, aber leider nicht alle...\n\nIch werde erstmal über diese Symbole brüten. Mit ein wenig Glück puzzle ich die Inschrift zusammen und komme dahinter, was sie aussagt.", sourceObjectiveStatus = "unverified-source-field" }
quests[77310] = { id = 77310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen einer Träumerin", description = "Im Traum können Erinnerungen auf ungewöhnliche Weise weiterleben. Erinnerungen sind nicht immer linear. Und fremde Erinnerungen können die Euren werden.\n\nVielleicht wurdet Ihr durch die Anwesenheit der ehemaligen Träumerin hergeführt. Oder vielleicht zieht es Euch wegen meiner guten Freundin an diesen Ort. Na kommt, seht Ihr es nicht?\n\nRastet hier und lasst Euch von der Magie des Traumes einhüllen.", sourceObjective = "Rastet im Auge von Ysera.", completion = "Gut, dass Ihr hier seid, {name}. Vielleicht könnt Ihr mir helfen?", sourceObjectiveStatus = "unverified-source-field" }
quests[77311] = { id = 77311, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilungshilfe", description = "Gracus hat Ysera gebeten, ihn zu treffen. Als wir ankamen, fanden wir ihn in einem üblen Zustand vor.\n\nUnsere Bemühungen, ihn zu heilen, blieben bisher erfolglos. Aber nun, da Ihr hier seid, könnt Ihr uns helfen.\n\nGracus gehört zum Traum. Vielleicht müssen wir seine Wurzeln mit etwas erfüllen, das hier wächst, um ihn endgültig wiederherzustellen.", sourceObjective = "Nutzt die Wurzelwiederherstellungsfrucht, um bei der Heilung von Gracus zu helfen.", progress = "Gracus' Zustand ist kritisch. Wir müssen alles tun, um zu helfen.", completion = "Ich war so sicher, dass wir helfen können.\n\nYsera scheint etwas hier zu spüren, das ich nicht wahrnehmen kann. Nach allem, was sie durchgemacht hat, scheint ihre Magie sich verändert zu haben, sodass ich sie nicht mehr verstehen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[77312] = { id = 77312, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Natur besteht", description = "Zugegeben, ich weiß nicht, was wir jetzt machen sollen.\n\nWenn er hier ruhen soll... wären Blumen schön.\n\nDie Schotlinge in der Nähe verstecken sich zwischen den Blumen. Sammelt Samen von ihnen, Champion, und ich werde sie erblühen lassen.\n\nIch glaube, Gracus wird die Blumen mögen.", sourceObjective = "Sammelt 6 aufkeimende Setzlinge von schleichenden Schotlingen.", progress = "Es muss noch irgendetwas geben, das wir...\n\nNein. Ysera wirkt sicher.", completion = "Bei solchen Gelegenheiten neues Wachstum anzuregen, fühlt sich richtig an.", sourceObjectiveStatus = "unverified-source-field" }
quests[77313] = { id = 77313, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine feierliche Versammlung", description = "Es ist, wie ich befürchtet habe. Gracus' Zeit ist gekommen.\n\nIhn zu heilen, hätte nie funktioniert. Die jenseitige Welt ruft bereits nach ihm.\n\nAuch wenn er in Frieden geht, werden alle, denen er etwas bedeutet, um ihn trauern. Wir werden ihn vermissen.\n\nNicht alle haben eine Gelegenheit, sich zu verabschieden.\n\nAber diesmal müssen wir sie ihnen verschaffen.", sourceObjective = "Informiert Gracus' Nahestehende.", progress = "Ich bin dankbar, dass wir ihnen diese Gelegenheit geben können, Abschied zu nehmen.", completion = "An diesem Ort ist es so friedlich.\n\nGracus hat mich aus einem guten Grund hergerufen. Er wusste es.", sourceObjectiveStatus = "unverified-source-field" }
quests[77314] = { id = 77314, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Totengedächtnis im Traum", description = "Ein Leben endet, doch ein anderes beginnt.\n\nWir müssen Gracus' geliebte Personen daran erinnern, {name}.\n\nPflanzt Samenkörner um Gracus herum ein. Meine Schwester kümmert sich um den Rest.\n\nDiese Stätte wird nicht nur ein Ende symbolisieren, sondern auch den Beginn neuen Lebens.", sourceObjective = "Pflanzt 6 Blumen um Gracus herum.", progress = "Diese Blumen werden um Gracus herum blühen und als Erinnerung an alles dienen, was er in seinem Leben gedeihen ließ.", completion = "Diese Erinnerungen... Gracus leidet. Wir sollte ihm helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77315] = { id = 77315, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Uralte Erinnerungen", description = "Diese dunklen Erinnerungen dürfen nicht im Traum wuchern.\n\nSie zu entfesseln, war notwendig. Gracus musste loslassen. Aber wenn sie hier verweilen, könnten sie bösartig werden.\n\nBesiegt die Erinnerung, die ihn am stärksten heimsucht, damit Gracus endlich ruhen kann.", sourceObjective = "Tötet die verbleibende Qual.", progress = "Gracus kann nicht ruhen, bis seine Erinnerungen beruhigt wurden.", completion = "Danke, {name}. Gracus hat nun seinen Frieden.\n\nSo wie diejenigen, denen er wichtig war, wie es scheint. Man bekommt nicht häufig eine zweite Gelegenheit, sich zu verabschieden.", sourceObjectiveStatus = "unverified-source-field" }
quests[77316] = { id = 77316, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ärger am Baum", description = "{name}! Merithra braucht Eure Hilfe.\n\nEinige garstige Trickserspriggans sind uns in den Traum gefolgt und richten jetzt überall Chaos an!\n\nDas Schlimmste ist, dass sie superstrenggeheime wichtige Vorräte gestohlen haben.\n\nIhr müsst sie dringend aufhalten und die Vorräte zurückholen.", sourceObjective = "Holt 6 sehr wichtige Baumvorräte von den Spriggans zurück.", progress = "Wenn wir diese Vorräte von diesen lästigen Spriggans nicht wiederbekommen, verlieren wir so viel Zeit!", completion = "Was für eine Erleichterung!\n\nNun, da wir diese wichtigen Vorräte zurückhaben, können wir uns wieder an die Arbeit machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[77317] = { id = 77317, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Behüteter Winterschaf", description = "Ich verrate Euch ein Geheimnis. Diese Vorräte? Das sind Scherzartikel!\n\nDie Leute hier sind so ernst. Und was gibt es Besseres als einen kleinen Streich, um jemandes Stimmung zu heben?\n\nIhr könntet einigen schlafenden Druiden hier diese lustigen Hüte aufsetzen. Was ist schon lustiger als ein Überraschungshut?\n\nSeid aber vorsichtig. Durch ihre Verbindung zum Traum könnte alles Mögliche passieren!", sourceObjective = "Setzt 6 träumenden Druiden lustige Hüte auf.", completion = "Ich bin beeindruckt. Ich dachte, ich würde Euch auch einen Streich spielen!\n\nAber scheinbar seid Ihr besser in diesen Dingen, als ich dachte... \n\nVielleicht ist es Zeit für eine echte Herausforderung.", sourceObjectiveStatus = "unverified-source-field" }
quests[77318] = { id = 77318, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merithra sagt...", description = "Einige Druiden haben sich freiwillig gemeldet, bei der Pflege des Baums und dem Errichten des Lagers zu helfen.\n\nAber sie sind so traurig!\n\n<Lady Mondbeere grinst verschlagen.>\n\nWir müssen ihnen einen Grund zum Lächeln geben. Ihr könntet ihnen befehlen, ein wenig Spaß zu haben.\n\nAber sie werden bestimmt keine Befehle von Euch annehmen.\n\nDeswegen habe ich Euch dieses Kostüm besorgt. Hiermit und mit einem kleinen Zauber werden sie Euch garantiert zuhören!", sourceObjective = "Gebt 5 Druiden Anweisungen, während Ihr als Merithra verkleidet seid.", progress = "Ihr seid eindeutig ein Meisterscherzkeks, aber Ihr müsst auch ein Meisterschauspieler sein.\n\nEin Kostüm und ein Zauber können Euch nur unterstützen.", completion = "Euer Auftritt als Merithra war unvergleichlich.\n\n<Lady Mondbeere bricht in Gelächter aus.>\n\nIch kann Euch kaum auseinanderhalten!", sourceObjectiveStatus = "unverified-source-field" }
quests[77322] = { id = 77322, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattrathsegelei", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77323] = { id = 77323, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattrathsegelei - Fortgeschritten", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77324] = { id = 77324, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattrathsegelei - Umgekehrt", description = "Fliegt durch die Kontrollpunktringe, die die Strecke markieren.", sourceObjective = "Gleitet durch die Ringe.", sourceObjectiveStatus = "unverified-source-field" }
quests[77325] = { id = 77325, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Archive!", description = "Seid Ihr ein Gelehrter, Historiker oder ein aufgeschlossener Intellektueller? Mögt Ihr schwere, stumpfsinnige Arbeiten im Austausch gegen Gold?\n\nDann ergreift Eure Zukunft und schließt Euch den aufstrebenden Rängen der Archive von Azeroth an!*\n\n<Ihr lest das Kleingedruckte am Ende der Seite.>\n\n* Das Büro ist vorrübergehend in der Akademie von Algeth'ar im nördlichen Thaldraszus zu finden.", sourceObjective = "Sprecht mit Oberarchivar Eadweard Dalyngrigge in der Akademie von Algeth'ar.", completion = "Endlich! Der Lieferdienst ist da mit unseren Essensbestellungen!\n\nOh... Ihr seid hier, um Euch den Archiven anzuschließen? Natürlich! Mein Fehler!\n\nAber wenn Euch jemand über den Weg läuft, der auch nur ein bisschen so aussieht, als würde er Essen liefern, dann schickt ihn zu mir, ja?", sourceObjectiveStatus = "unverified-source-field" }
quests[77327] = { id = 77327, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nirobin und das Büro", description = "Vielleicht gibt es hier noch mehr zu untersuchen, aber ich brauche Zeit, um mir unsere Funde anzusehen.\n\nUnser Kollege, Nirobin, der sich selbst arkan ins Hauptquartier projiziert, sollte jetzt bereit für Eure Hilfe sein. Er hat sein eigenes Büro in der Akademie in Thaldraszus, in dem er sich gerne vergräbt.\n\nIch bin sicher, dass er dort ist... Hauptsächlich, weil er es nie verlässt.", sourceObjective = "Sprecht mit Nirobin in seinem Büro in Thaldraszus.", completion = "Seid Ihr der neue Rekrut?\n\nDa Ihr spät dran seid, hatte ich einfach angenommen, das Draußen hätte Euch verschluckt... wie es mir in meinen immer wiederkehrenden Alpträumen widerfährt.\n\nEs ist schön, Euch persönlich zu treffen, schätze ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[77328] = { id = 77328, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück ins Hauptquartier!", description = "Eadweard hat Euch in unser Hauptquartier zurückgerufen, nachdem ich mit Euch fertig bin... ich meine, mit diesem Experiment.\n\nIch bin sicher, es geht um Prunk, Sachlage, Belohnung und dergleichen. Wenn Euch irgendetwas davon anspricht, solltet Ihr Euch beeilen, bevor er alle seine Geschenke an die anderen neuen Rekruten verteilt.", sourceObjective = "Trefft Euch mit Eadweard Dalyngrigge in der Akademie von Algeth'ar in Thaldraszus.", completion = "Roska und Zenata dachten, Ihr würdet nur wegen des Goldes mitmachen wie alle anderen. \n\nAber nicht ich! Ich hielt Euch für... Nein, doch nicht. Ich dachte tatsächlich auch, Ihr wärt nur wegen des Goldes hier.\n\nAber vergesst das! Seht das als den Beginn Eurer Geschichte als Archivar von Azeroth.\n\nWillkommen im Team!", sourceObjectiveStatus = "unverified-source-field" }
quests[77329] = { id = 77329, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verheißungsvolle Versammlung", description = "Wie Ihr wisst, ist Amirdrassil kein gewöhnlicher Baum. Tyrande Wisperwind und die anderen Kaldorei haben sich darauf vorbereitet, ihn mit einer eigenen Zeremonie gebührend zu empfangen und einen neuen Mondbrunnen zu errichten.\n\nIch bin mir sicher, dass Tyrande Euch bei der Einweihung dabei haben möchte.\n\nSchließen wir uns ihnen beim Zentrallager an.", sourceObjective = "Sprecht mit Tyrande Wisperwind im Zentrallager.", completion = "Amirdrassil ist alles, was wir uns erhofft haben. Lasst uns seine Ankunft gebührend feiern.", sourceObjectiveStatus = "unverified-source-field" }
quests[77331] = { id = 77331, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abschlusstag", description = "Ihr habt Euch zu einem guten Mitglied unserer Truppe Buddler gemausert.\n\nZwischen den Stätten habt Ihr Euch mit Roska, Zenata und Nirobin angefreundet und mit dem Großen bei der Ruhestätte des Verräters. Die Geschichte der Dracheninseln war noch nie so erntereif.\n\nHier wird es immer Arbeit und Kameradschaft geben, wenn Ihr welche sucht. Wir hoffen, dass Ihr Euch uns auch auf anderen Kontinenten anschließt...\n\n...das heißt, wenn wir die nötige Finanzierung bekommen.", sourceObjective = "Erhaltet Lob von Euren Kollegen der Archivare von Azeroth.", completion = "Auf Euch, {name}!\n\nAuf Eure Unterstützung, Euren Entdeckergeist und Eure Sorgfalt mit der Geschichte!\n\nMögen alle mit freudigem Appetit auf Wissen Heimat und Freunde wie diese finden!", sourceObjectiveStatus = "unverified-source-field" }
quests[77339] = { id = 77339, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Datenwiederbeschaffung", description = "Nach einer kurzen Erholung und mehr intensiven Übungen ist unsere Zeit endlich gekommen! Travard glaubt, Tyrs Wache ist bereit, die Scheibe von Tyr aus der Nachtfestung zurückzuholen.\n\nWir treffen uns bei Tyrs Ruhestätte, dem neuen Hauptquartier von Tyrs Wache. Es liegt gleich südlich von Tyrhold.\n\nEndlich werden wir Tyr wieder ganz machen!", sourceObjective = "Trefft Travard im Hauptquartier von Tyrs Wache.", completion = "Da seid Ihr ja, {name}. Bereit, uns endlich diese Scheibe zurückzuholen?", sourceObjectiveStatus = "unverified-source-field" }
quests[77340] = { id = 77340, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltration der Nachtfestung", description = "Den Informationen unserer Leuchtfeuer nach hat Elisande die Scheibe im Stieg des Astromanten weggesperrt.\n\nDas ist ein Ort des Lernens und im Inneren werden die Schutzmaßnahmen nur minimal sein. Ich habe ein Portal zu einem Ort geöffnet, an dem Ihr und Tyrs Wache auf den geringsten Widerstand stoßen solltet... ausgenommen natürlich Elisande und ihre persönlichen Wachen.\n\nSobald Ihr dort eintrefft, werdet Ihr auf Euch allein gestellt sein, also vermasselt es bitte nicht.", sourceObjective = "Holt Euch die Scheibe von Tyr von Elisande in der Nachtfestung zurück.", progress = "Ich frage mich, wie Tyr wohl sein wird. Er ist sicher unglaublich nett!", completion = "Ich bin froh, dass es alle geschafft haben, {name}! Wir haben die Scheibe, die Silberschuppe und Tyr wurde neu geschmiedet. Unglaublich! Bringen wir Tyr zurück!", sourceObjectiveStatus = "unverified-source-field" }
quests[77341] = { id = 77341, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Logotyrapie", sourceObjective = "Sprecht mit Tyr in Tyrs Ruhestätte.", progress = "Tyr wirkt völlig rastlos. Vielleicht könntet Ihr mit ihm sprechen, {name}?", completion = "Ich hoffe, {name}, wir finden den höheren Zweck, für den wir neu geschmiedet wurden. Für Tyr und Tyrs Wache gleichermaßen.\n\nVielleicht ist diese Suche der nächste Abschnitt auf unserer Reise.", sourceObjectiveStatus = "unverified-source-field" }
quests[77342] = { id = 77342, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scheibenlieferung", sourceObjective = "Legt die Scheibe von Tyr in die Titanenschalttafel ein.", progress = "Habt ihr die Scheibe in die Titanenschalttafel eingelegt?", completion = "Tyr ist wieder bei uns. Ich kann es kaum glauben. Ich danke Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
